-- Everest Trek: the German words (informal "du", its brand guide) of the content copied from Travel To Nepal in
-- 20261118110000_everest_site.sql (decided 2026-11-18: Claude drafts, the owner reviews in the admin; legal texts need a
-- lawyer). Generated from checked JSON (same shape as the English, only words changed); only changed values.
-- About, Contact and the legal pages start from Annapurna Trekking's German pages, rewritten in du-form for Everest.
-- Money: the treks' own prices are written in euros (the website's currency), other amounts keep their currency.
-- Then: Home and the blog page's top, German web addresses, and no old addresses (the website was never live).

-- Treks: their texts, days and group prices
update public.trek_translations set faqs = $de$[{"icon": "calendar_month", "items": [{"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Sonnenaufgang auf dem Kala Patthar mit Blick auf den Everest, das Everest Base Camp am Khumbu-Eisbruch, Namche Bazar, das Kloster Tengboche unter der Ama Dablam und die Sherpa-Dörfer am Weg.", "type": "text"}]}]}, "question": "Was sind die Highlights des Everest Base Camp Treks?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Der Kala Patthar mit 5.545 m an Tag 10. In der Nacht davor schläfst du in Gorak Shep (5.164 m), so hoch wie in keiner anderen Nacht auf dem Trek.", "type": "text"}]}]}, "question": "Was ist der höchste Punkt des Treks?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Oktober und November bieten die klarste Sicht, danach März bis Mai, wenn die Expeditionen im Basislager sind. Der Winter ist klar, aber sehr kalt, und der Monsun bringt Wolken und gestrichene Flüge.", "type": "text"}]}]}, "question": "Wann ist die beste Reisezeit?"}], "title": "Allgemeine Informationen"}, {"icon": "nordic_walking", "items": [{"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Unser Reiseverlauf dauert 14 Tage ab und bis Kathmandu, davon 11 Tage auf dem Trail mit zwei Akklimatisierungstagen. Plane ein oder zwei Puffertage für Verspätungen beim Lukla-Flug ein.", "type": "text"}]}]}, "question": "Wie lange dauert der Everest Base Camp Trek?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Ab Kathmandu, doch in der vollen Frühjahrs- und Herbstsaison starten die meisten Flüge in Ramechhap (Manthali), 3–4 Std. Fahrt von Kathmandu mit sehr frühem Aufbruch. Den Transfer organisieren wir.", "type": "text"}]}]}, "question": "Wo starten die Flüge nach Lukla?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Die Flüge hängen vom Wetter ab, und Verspätungen von einem Tag oder mehr kommen vor. Wir halten dich auf dem Laufenden, buchen dich auf den nächsten Flug um und können einen Helikopter organisieren, wenn du einen festen Termin einhalten musst.", "type": "text"}]}]}, "question": "Was passiert, wenn sich mein Lukla-Flug verspätet?"}], "title": "Reiseverlauf und Flüge"}, {"icon": "fitness_center", "items": [{"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Anspruchsvoll, Stufe 4 von 5. Geklettert wird nicht, aber lange Tage über 4.000 m und kalte Nächte verlangen eine gute Kondition und Geduld mit der Höhe.", "type": "text"}]}]}, "question": "Wie schwer ist der Everest Base Camp Trek?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Bergwanderungen mit beladenem Tagesrucksack, Treppensteigen und regelmäßiges Ausdauertraining über 8–12 Wochen vor der Reise. Am besten trainierst du mit mehreren langen Wandertagen hintereinander.", "type": "text"}]}]}, "question": "Wie sollte ich trainieren?"}], "title": "Schwierigkeit und Fitness"}, {"icon": "medical_services", "items": [{"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Ruhetage in Namche und Dingboche, ein langsames Tempo, zweimal täglich Sauerstoff- und Pulsmessung, viel trinken und sofort absteigen, wenn ernste Symptome auftreten.", "type": "text"}]}]}, "question": "Wie beugt ihr der Höhenkrankheit vor?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Dein Guide hat ein Erste-Hilfe-Set und ein Pulsoximeter dabei. Wenn nötig, organisiert unser Büro in Kathmandu mit deiner Versicherung eine Helikopterevakuierung.", "type": "text"}]}]}, "question": "Was passiert im Notfall?"}], "title": "Höhe und Gesundheit"}]$de$::jsonb, summary = $de$Sherpa-Dörfer, das Kloster Tengboche und ein Sonnenaufgang auf dem Kala Patthar mit Blick auf den Everest.$de$, activity = $de$Trekking / Wandern$de$, category = $de$Klassischer Höhentrek$de$, excluded = $de$[{"text": "bestell frei von der Karte (etwa USD 30–40 pro Tag; die Preise steigen mit der Höhe).", "title": "Essen auf dem Trek"}, {"text": "Flüge nach und ab Kathmandu.", "title": "Internationale Flüge"}, {"text": "Pflicht, mit Deckung für eine Helikopterrettung bis 6.000 m.", "title": "Reiseversicherung"}, {"text": "bei der Ankunft am Flughafen.", "title": "Touristenvisum für Nepal"}, {"text": "warme Duschen, Akkuladen und WLAN.", "title": "Extras in der Lodge"}]$de$::jsonb, headline = $de$Everest Base Camp Trek in 14 Tagen (Reiseverlauf, Kosten, alle Infos)$de$, included = $de$[{"text": "Kathmandu (oder Ramechhap) – Lukla – Kathmandu, bei Bedarf mit dem Transfer nach Ramechhap.", "title": "Inlandsflüge"}, {"text": "in Erster Hilfe ausgebildet, versichert und fair bezahlt.", "title": "Lizenzierter Guide und Träger"}, {"text": "11 Nächte auf dem Trek und 2 Hotelnächte in Kathmandu.", "title": "Übernachtung in Teehäusern"}, {"text": "Genehmigung für den Sagarmatha-Nationalpark und lokale Genehmigung der Gemeinde Khumbu Pasang Lhamu.", "title": "Genehmigungen"}, {"text": "Pulsoximeter und Erste-Hilfe-Set, mit zweimal täglicher Sauerstoffmessung.", "title": "Sicherheitsausrüstung"}, {"text": "Ankunft und Abreise in Kathmandu.", "title": "Flughafentransfers"}]$de$::jsonb, days_note = $de$ab und bis Kathmandu$de$, seo_title = $de$Everest Base Camp Trek 14 Tage: Reiseverlauf, ab 1.000 €$de$, transport = $de$Flug nach Lukla$de$, card_badge = $de$Ein Trek fürs Leben$de$, highlights = $de$[{"text": "Der klassische Aussichtspunkt über Gorak Shep: Everest, Nuptse und Lhotse leuchten direkt vor dir.", "title": "Sonnenaufgang auf dem Kala Patthar (5.545 m)"}, {"text": "Steh direkt am Khumbu-Gletscher und am Eisbruch, wo im Frühjahr die Expeditionen ihr Lager aufschlagen.", "title": "Everest Base Camp (5.364 m)"}, {"text": "Die Hauptstadt der Sherpa, mit Bäckereien, einem Samstagsmarkt und deinem ersten Blick auf den Everest vom Hügel über dem Ort.", "title": "Namche Bazar"}, {"text": "Das größte Kloster im Khumbu, direkt dahinter ragt die Ama Dablam auf.", "title": "Kloster Tengboche (3.867 m)"}, {"text": "Gebetsfahnen, Manimauern, Chörten und Dörfer, in denen das Bergsteigen die Geschichte jeder Familie geprägt hat.", "title": "Sherpa-Kultur"}, {"text": "Ein kurzer, spektakulärer Flug zu einer der berühmtesten Landepisten der Bergwelt.", "title": "Der Bergflug nach Lukla"}]$de$::jsonb, know_intro = $de$Wichtiges Wissen von unseren einheimischen Trekkingleitern.$de$, route_line = $de$Route des Everest Base Camp Treks im Überblick (Lukla – Namche Bazar – Gorak Shep)$de$, faq_heading = $de$Häufige Fragen zum Everest Base Camp Trek$de$, guide_ratio = $de$1 : 4 + Träger$de$, know_topics = $de$[{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Herbst (Oktober bis November):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " der klarste Himmel des Jahres und die zuverlässigsten Flüge nach Lukla.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Frühling (März bis Mai):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " wärmere Tage, blühende Rhododendren unterhalb von Namche und die Zelte der Expeditionen im Basislager.", "type": "text"}]}]}, "icon": "wb_twilight", "note": "Der Winter (Dez.–Feb.) ist klar, doch nachts fällt das Thermometer in Gorak Shep unter −20 °C. Der Monsun (Juni–Sept.) bringt Wolken und häufig gestrichene Flüge.", "title": "Beste Reisezeit und Wetterfenster", "photoId": null, "videoId": null}, {"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Zimmer:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Zweibettzimmer mit Schaumstoffmatratzen; oberhalb von Dingboche einfacher und kälter.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Heizung und Duschen:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Abends wärmt ein Ofen, in dem Yakdung brennt, den Speiseraum; eine warme Dusche kostet ein paar Dollar.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "WLAN und Strom:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " In den meisten Lodges gibt es WLAN-Karten und Ladestrom gegen Gebühr; weiter oben liefert die Solaranlage weniger Strom.", "type": "text"}]}]}, "icon": "cottage", "note": "", "title": "Unterkunft und Ausstattung der Teehäuser", "photoId": null, "videoId": null}, {"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Dal Bhat:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Reis, Linsensuppe, Gemüse und Pickles, mit kostenlosem Nachschlag.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Speisekarten am Trail:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Knoblauchsuppe, Sherpa-Eintopf, Porridge, Nudeln, Pasta und Ingwertee.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Trinken:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Trink 3–4 Liter am Tag und bereite dein Wasser auf; Nachfüllstationen sparen Plastik.", "type": "text"}]}]}, "icon": "soup_kitchen", "note": "", "title": "Essen, Ernährung und sicheres Wasser", "photoId": null, "videoId": null}, {"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Rettung:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Unser Büro in Kathmandu organisiert mit deiner Versicherung eine Helikopterevakuierung, falls sie je nötig wird.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Unterwegs:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Dein Guide hat ein Erste-Hilfe-Set und ein Pulsoximeter dabei; in Pheriche gibt es in der Saison eine Höhenklinik.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Versicherung:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Jeder Trekker braucht eine Reiseversicherung, die Evakuierungen bis 6.000 m abdeckt.", "type": "text"}]}]}, "icon": "emergency", "note": "", "title": "Notfallplan und Helikopterevakuierung", "photoId": null, "videoId": null}]$de$::jsonb, seo_keyword = $de$Everest Base Camp Trek$de$, guides_intro = $de$Lizenzierte Guides aus dem Khumbu und den Hügeln des Solu, ausgebildet in Wildnis-Erster-Hilfe und mit dem Fokus auf eine sichere Akklimatisierung.$de$, introduction = $de${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Der Everest Base Camp Trek ist die klassische Wanderung zum Fuß des höchsten Bergs der Erde. Ein kurzer Bergflug bringt dich nach Lukla (2.860 m). Von dort folgt der Weg dem Fluss Dudh Koshi nach Namche Bazar, der Hauptstadt der Sherpa, und weiter am Kloster Tengboche vorbei in die hohen Täler unter Lhotse und Ama Dablam.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Der Trek führt bis zum Everest Base Camp (5.364 m) am Khumbu-Eisbruch, und am nächsten Morgen steigst du auf den Kala Patthar (5.545 m), wo du den schönsten Sonnenaufgang über dem Everest (8.849 m) erlebst. Es ist ein langer Trek in großer Höhe, deshalb planen wir zwei Akklimatisierungstage in Namche und Dingboche ein und steigen langsam auf.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Jede Nacht verbringst du in einem Teehaus, das eine Sherpa-Familie führt, und dein Guide stammt aus dem Khumbu oder den Hügeln direkt darunter.", "type": "text"}]}]}$de$::jsonb, know_heading = $de$Ratgeber zum Everest Base Camp Trek: Reisezeit, Teehäuser und Höhe$de$, packing_line = $de${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Erprobte Ausrüstung für den Khumbu: von −15 °C in den Nächten in Gorak Shep bis zu warmen, sonnigen Tagen im unteren Tal.", "type": "text"}]}]}$de$::jsonb, photo_badges = $de$[{"icon": "health_and_safety", "tone": "brand", "label": "Zwei Akklimatisierungstage"}, {"icon": "nordic_walking", "tone": "green", "label": "Mit Sherpa-Guide"}, {"icon": "landscape", "tone": "brand", "label": "Sonnenaufgang am Kala Patthar"}]$de$::jsonb, season_label = $de$März–Mai, Okt.–Nov.$de$, accommodation = $de$Teehaus und Hotel$de$, daily_walking = $de$5 bis 7 Std. am Tag$de$, packing_intro = $de$Erprobte Ausrüstung für den Khumbu: von −15 °C in den Nächten in Gorak Shep bis zu warmen, sonnigen Tagen im unteren Tal.$de$, pricing_intro = $de$Buche direkt bei unserem Team in Kathmandu, ohne Zwischenhändler. Jeder Trek ist privat, du wählst also dein eigenes Startdatum.$de$, similar_intro = $de$Treks, die wir mit dir planen und die einheimische Guides führen.$de$, elevation_note = $de$Du übernachtest bis auf 5.164 m in Gorak Shep und wanderst als Tagestour zum Basislager und auf den Kala Patthar.$de$, guides_heading = $de$Lerne deinen Guide kennen$de$, packing_groups = $de$[{"icon": "apparel", "items": [{"text": "2–3 Oberteile und Hosen aus Merino oder Kunstfaser.", "title": "Funktionsunterwäsche"}, {"text": "eine warme Fleece- oder Softshelljacke.", "title": "Fleece als Zwischenschicht"}, {"text": "ausgelegt auf etwa −15 °C für Lobuche und Gorak Shep.", "title": "Daunenjacke"}, {"text": "Jacke und Hose gegen Wind und Schnee.", "title": "Wasserdichte Hardshell"}], "title": "Kleidung und Zwiebelprinzip"}, {"icon": "footprint", "items": [{"text": "wasserdicht, eingelaufen und mit Halt am Knöchel.", "title": "Trekkingschuhe"}, {"text": "leichte Turnschuhe oder Sandalen fürs Teehaus.", "title": "Hüttenschuhe"}, {"text": "4–5 Paar gepolsterte Trekkingsocken, dazu ein warmes Paar für die Nacht.", "title": "Socken"}, {"text": "praktisch auf vereisten Wegen im frühen Frühjahr oder späten Herbst.", "title": "Grödel (Microspikes)"}], "title": "Schuhe und Fußpflege"}, {"icon": "backpack", "items": [{"text": "mit Regenhülle, für Kleidung, Wasser und Snacks.", "title": "Tagesrucksack (25–35 l)"}, {"text": "trägt dein Träger (max. 15 kg; bei den Lukla-Flügen ist das Gepäck begrenzt).", "title": "Duffelbag"}, {"text": "Komfortbereich bis −15 °C (du kannst einen in Kathmandu leihen).", "title": "Schlafsack"}, {"text": "für die Abstiege und den Sonnenaufgang am Kala Patthar.", "title": "Trekkingstöcke und Stirnlampe"}], "title": "Ausrüstung und Gepäck"}, {"icon": "medical_services", "items": [{"text": "Tabletten oder ein UV-Stift, dazu zwei 1-l-Flaschen.", "title": "Wasseraufbereitung"}, {"text": "Blasenpflaster, Schmerzmittel, Elektrolytpulver und deine eigenen Medikamente.", "title": "Reiseapotheke"}, {"text": "Sonnencreme mit LSF 50, Lippenpflege und eine Sonnenbrille der Kategorie 3–4.", "title": "Sonnenschutz"}, {"text": "Feuchttücher, Handdesinfektion und ein schnell trocknendes Handtuch.", "title": "Hygiene"}], "title": "Gesundheit, Hygiene und Wasser"}]$de$::jsonb, protected_area = $de$Sagarmatha-Nationalpark$de$, itinerary_intro = $de${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "14 Tage von Kathmandu bis zum Fuß des Everest und zurück. Du fliegst nach Lukla, steigst über Namche Bazar und Tengboche langsam auf, mit Ruhetagen in Namche und Dingboche, erreichst das Everest Base Camp und stehst zum Sonnenaufgang auf dem Kala Patthar, bevor du durch das Khumbu-Tal wieder absteigst. Jede Nacht auf dem Trail verbringst du in einem familiengeführten Teehaus.", "type": "text"}]}]}$de$::jsonb, meal_trail_tips = $de$[{"text": "Reis, Linsen und Gemüsecurry mit Nachschlag, so viel du willst. Der beste Treibstoff in der Höhe.", "title": "„Dal-Bhat-Power“"}, {"text": "Fleisch wird von Trägern und Yaks hinaufgebracht, deshalb empfehlen wir oberhalb von Namche vegetarisches Essen.", "title": "Weiter oben vegetarisch essen"}, {"text": "trink 3–4 Liter am Tag (Ingwer-Zitronen-Honig-Tee, Knoblauchsuppe, abgekochtes Wasser).", "title": "Genug trinken"}, {"text": "In Namche gibt es Geldautomaten, aber sie sind oft leer. Nimm genug Nepalesische Rupien aus Kathmandu mit.", "title": "Bargeld ist Trumpf"}]$de$::jsonb, packing_heading = $de$Packliste für den Everest Base Camp Trek$de$, pricing_heading = $de$Gruppenpreise nach Teamgröße$de$, seo_description = $de$Privater Everest Base Camp Trek in 14 Tagen mit Sherpa-Guide: Flug nach Lukla, Namche, Tengboche, zwei Ruhetage und Sonnenaufgang am Kala Patthar (5.545 m).$de$, similar_heading = $de$Ähnliche Treks in Nepal$de$, elevation_heading = $de$Route und Höhenprofil$de$, itinerary_heading = $de$Reiseverlauf Tag für Tag$de$, route_map_heading = $de$Routenkarte zum Everest Base Camp Trek$de$, suitability_intro = $de$Eine ehrliche Checkliste unserer Guides, damit du entscheiden kannst, ob das Everest Base Camp der richtige Trek für dich ist.$de$, highlights_heading = $de$Highlights des Everest Base Camp Treks und warum du ihn lieben wirst$de$, inclusions_heading = $de$Inklusive · Nicht inklusive$de$, suitability_points = $de$[{"text": "5 bis 7 Std. Gehzeit am Tag über 11 Tage mit leichtem Tagesrucksack. Für die langen Anstiege brauchst du eine gute Ausdauer.", "title": "Körperliche Anforderungen und Fitness"}, {"text": "Du schläfst auf 5.164 m in Gorak Shep und steigst bis auf 5.545 m. Zwei Ruhetage helfen, aber die eigentliche Herausforderung ist die Höhe.", "title": "Höhe und Akklimatisierung"}, {"text": "Keine. Felsige Pfade, Steinstufen und Moränen. In den Trekkingsaisons brauchst du weder Seile noch Steigeisen oder Kletterausrüstung.", "title": "Technisches Können"}, {"text": "Teehäuser mit Zweibettzimmern und warmen Speiseräumen. Weiter oben einfacher und kälter, mit Gemeinschaftstoiletten.", "title": "Komfort und Unterkunft unterwegs"}, {"text": "Rechne mit kalten Nächten, schlechtem Schlaf in der Höhe und möglichen Flugverspätungen in Lukla. Gelassenheit hilft.", "title": "Mentale Stärke"}, {"text": "Wenn du Herz- oder Lungenprobleme oder schweres Asthma hast, sprich vor der Buchung eines so hohen Treks mit deinem Arzt.", "title": "Gesundheitliche Voraussetzungen"}]$de$::jsonb, meal_teahouse_notes = $de$[{"text": "Frühstück und Abendessen nimmst du dort ein, wo du schläfst. Nur deshalb können die Lodges ihre Zimmerpreise so niedrig halten.", "title": "Teehaus-Regel"}, {"text": "bestell das Abendessen gegen 17 Uhr und sag am Abend vorher, wann du frühstücken möchtest.", "title": "Früh bestellen"}, {"text": "alles wird hinaufgetragen, deshalb kostet ein Essen in Gorak Shep etwa doppelt so viel wie in Namche.", "title": "Die Preise steigen mit der Höhe"}]$de$::jsonb, suitability_heading = $de$Ist dieser Trek etwas für dich?$de$ where trek_id = '07f7800f-1aee-46e8-bff6-ba3f2f15f9ba' and locale = 'de';
update public.trek_day_translations set title = $de$Ankunft in Kathmandu (1.400 m), Begrüßung und Briefing$de$, duration = $de$Ankunft$de$, subtitle = $de$Abholung am Flughafen · Ausrüstungscheck in Thamel$de$, description = $de${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Unser Team empfängt dich am Tribhuvan International Airport und bringt dich ins Hotel. Am Abend prüfen wir deine Ausrüstung, kümmern uns um die Genehmigungen und bestätigen deinen Flug nach Lukla.", "type": "text"}]}]}$de$::jsonb where day_id = '3bcf745b-1ce6-4443-befe-ae8cc29f048f' and locale = 'de';
update public.trek_day_translations set title = $de$Flug nach Lukla (2.860 m) und Wanderung nach Phakding (2.610 m)$de$, duration = $de$3–4 Std.$de$, subtitle = $de$Bergflug · Tal des Dudh Koshi$de$, description = $de${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Ein früher Flug nach Lukla, ab Kathmandu oder in der Hochsaison ab Ramechhap. Ein kurzer, sanfter Abstieg am Fluss entlang bringt dich nach Phakding, wo du übernachtest.", "type": "text"}]}]}$de$::jsonb where day_id = 'e85831f1-0df2-42c4-b413-4eefb5374a43' and locale = 'de';
update public.trek_day_translations set place = $de$Namche Bazar$de$, title = $de$Von Phakding nach Namche Bazar (3.440 m)$de$, duration = $de$6–7 Std.$de$, subtitle = $de$Hillary-Brücke · Erster Blick auf den Everest$de$, description = $de${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Auf Hängebrücken überquerst du mehrmals den Fluss und betrittst in Monjo den Sagarmatha-Nationalpark. Nach der hohen Hillary-Brücke endet der lange Aufstieg in Namche Bazar.", "type": "text"}]}]}$de$::jsonb where day_id = 'e598a294-901a-4289-99b1-aee18ceaad87' and locale = 'de';
update public.trek_day_translations set place = $de$Namche Bazar$de$, title = $de$Akklimatisierungstag in Namche, Wanderung zum Everest View Hotel (3.880 m)$de$, duration = $de$3–4 Std.$de$, subtitle = $de$Ruhetag · Dorf Khumjung$de$, description = $de${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Hoch steigen, tief schlafen: Am Morgen wanderst du über den Ort hinauf, mit Blick auf Everest und Ama Dablam, und wenn du dich fit fühlst, besuchst du Khumjung. Der Nachmittag in Namche ist frei.", "type": "text"}]}]}$de$::jsonb where day_id = '60f44632-423e-40f2-914f-1efafb431900' and locale = 'de';
update public.trek_day_translations set title = $de$Von Namche Bazar nach Tengboche (3.867 m)$de$, duration = $de$5–6 Std.$de$, subtitle = $de$Höhenweg · Kloster Tengboche$de$, description = $de${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Ein wunderschöner Höhenweg mit der Ama Dablam vor dir, dann hinab zum Fluss bei Phunki Tenga und ein stetiger Aufstieg durch den Wald nach Tengboche. Am Nachmittag besuchst du das Kloster.", "type": "text"}]}]}$de$::jsonb where day_id = '0c4a84ce-bf44-4ad3-99e0-addbcbcdc299' and locale = 'de';
update public.trek_day_translations set title = $de$Von Tengboche nach Dingboche (4.410 m)$de$, duration = $de$5–6 Std.$de$, subtitle = $de$Dorf Pangboche · Über der Baumgrenze$de$, description = $de${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Durch Rhododendronwald nach Pangboche und über die Baumgrenze hinaus ins Imja-Tal. Dingboche liegt zwischen steinummauerten Feldern unter der Ama Dablam und dem Island Peak.", "type": "text"}]}]}$de$::jsonb where day_id = 'f500e731-7670-49e9-bf2b-09ed080d821b' and locale = 'de';
update public.trek_day_translations set title = $de$Akklimatisierungstag in Dingboche, Aufstieg auf den Nangkartshang (etwa 5.080 m)$de$, duration = $de$4–5 Std.$de$, subtitle = $de$Ruhetag · Blick auf Makalu und Lhotse$de$, description = $de${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Ein langsamer Aufstieg über den Grat oberhalb von Dingboche mit Blick auf Makalu, Lhotse und Ama Dablam, dann zurück zum Ausruhen. Dieser Tag macht dir die nächsten Etappen viel leichter.", "type": "text"}]}]}$de$::jsonb where day_id = '73e7f220-177f-45e5-b25c-ec8eb9b23db9' and locale = 'de';
update public.trek_day_translations set title = $de$Von Dingboche nach Lobuche (4.940 m)$de$, duration = $de$5–6 Std.$de$, subtitle = $de$Gedenkstätten am Thukla-Pass · Khumbu-Gletscher$de$, description = $de${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Über ein weites Tal nach Thukla, dann die steile Moräne hinauf zu den Gedenksteinen für die Bergsteiger am Thukla-Pass. Ein sanfterer Weg am Khumbu-Gletscher entlang führt nach Lobuche.", "type": "text"}]}]}$de$::jsonb where day_id = '550d1150-9cce-4e6c-9b3f-b4a74ff50f19' and locale = 'de';
update public.trek_day_translations set title = $de$Von Lobuche nach Gorak Shep (5.164 m) und zum Everest Base Camp (5.364 m)$de$, duration = $de$7–8 Std.$de$, subtitle = $de$Khumbu-Eisbruch · Basislager$de$, description = $de${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Ein felsiger Weg am Gletscher entlang nach Gorak Shep zum Mittagessen, dann weiter zum Everest Base Camp am Khumbu-Eisbruch. Übernachtung wieder in Gorak Shep.", "type": "text"}]}]}$de$::jsonb where day_id = '15621c7e-ae82-4c8e-a2de-9684bada9a15' and locale = 'de';
update public.trek_day_translations set title = $de$Sonnenaufgang auf dem Kala Patthar (5.545 m), Abstieg nach Pheriche (4.371 m)$de$, duration = $de$7–8 Std.$de$, subtitle = $de$Der höchste Punkt des Treks · Der Everest zum Greifen nah$de$, description = $de${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Noch vor der Dämmerung steigst du auf den Kala Patthar, wo die Sonne über Everest, Nuptse und Pumori aufgeht. Zurück in Gorak Shep gibt es Frühstück, dann folgt ein langer Abstieg nach Pheriche, wo sich die Luft wieder dichter anfühlt.", "type": "text"}]}]}$de$::jsonb where day_id = '387e167c-db7f-447a-8e74-475c6426637b' and locale = 'de';
update public.trek_day_translations set place = $de$Namche Bazar$de$, title = $de$Von Pheriche nach Namche Bazar (3.440 m)$de$, duration = $de$6–7 Std.$de$, subtitle = $de$Zurück über Pangboche und Tengboche$de$, description = $de${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Du gehst das Tal zurück, vorbei an Pangboche und Tengboche, mit einem letzten Anstieg vor dem Weg nach Namche. Eine warme Dusche und etwas Süßes aus der Bäckerei hast du dir verdient.", "type": "text"}]}]}$de$::jsonb where day_id = 'da577c1b-d0c1-4b62-b072-ee84d6e4f0ba' and locale = 'de';
update public.trek_day_translations set title = $de$Von Namche Bazar nach Lukla (2.860 m)$de$, duration = $de$6–7 Std.$de$, subtitle = $de$Letzter Trekkingtag · Feiern mit deinem Team$de$, description = $de${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Der letzte Abstieg zum Fluss und wieder hinauf nach Lukla, wo wir mit deinem Guide und den Trägern das Ende des Treks feiern.", "type": "text"}]}]}$de$::jsonb where day_id = '8746ca0d-1ac2-4283-8018-9b021458397c' and locale = 'de';
update public.trek_day_translations set title = $de$Flug von Lukla nach Kathmandu (1.400 m)$de$, duration = $de$35 Min. Flug$de$, subtitle = $de$Morgenflug · Freier Nachmittag$de$, description = $de${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Ein früher Flug zurück nach Kathmandu, in der Hochsaison nach Ramechhap und weiter mit dem Auto in die Stadt. Der Rest des Tages ist frei für ein Abschiedsessen.", "type": "text"}]}]}$de$::jsonb where day_id = 'cdb5bb6c-adfc-4751-b175-53561533adff' and locale = 'de';
update public.trek_day_translations set title = $de$Abreise oder Verlängerung deines Aufenthalts in Nepal$de$, subtitle = $de$Flughafentransfer · Puffertag für Flugverspätungen$de$, description = $de${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Transfer zum Flughafen für deinen Heimflug. Wir empfehlen dir, einen Puffertag einzuplanen, falls sich der Lukla-Flug wegen des Wetters verspätet.", "type": "text"}]}]}$de$::jsonb where day_id = '5371bdce-67c7-46f7-9a1f-ecdd9656efa9' and locale = 'de';
update public.trek_group_price_translations set team = $de$Privater Guide + privater Träger$de$, label = $de$1 Person (allein)$de$, short_label = $de$1 Pers.$de$ where price_id = '9c58a284-1048-416f-96bd-5edc36f036d4' and locale = 'de';
update public.trek_group_price_translations set team = $de$Guide + 1 Träger$de$, label = $de$2 Personen$de$, short_label = $de$2 Pers.$de$ where price_id = '69549a54-c02c-4883-bd5b-92eae2196633' and locale = 'de';
update public.trek_group_price_translations set team = $de$Leitender Guide + Assistent + Träger$de$, label = $de$3–5 Personen$de$, short_label = $de$3–5 Pers.$de$ where price_id = '7717f762-e50c-4074-bb33-6694ea7e546a' and locale = 'de';
update public.trek_group_price_translations set team = $de$Leitender Guide + 2 Assistenten + Träger$de$, label = $de$6–10 Personen$de$ where price_id = 'de4777f1-c6a1-4a1d-bb15-e21ebcb441f2' and locale = 'de';
update public.trek_group_price_translations set team = $de$Komplettes Trekkingteam$de$, label = $de$11+ Personen$de$, short_label = $de$11+ Pers.$de$ where price_id = 'ceec5b06-1671-4c94-8db1-425ec2a287bb' and locale = 'de';
update public.trek_translations set faqs = $de$[{"icon": "calendar_month", "items": [{"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Der Sonnenaufgang auf dem Gokyo Ri mit vier Achttausendern im Blick, die türkisblauen Gokyo-Seen, der Ngozumpa-Gletscher, Namche Bazar und stille Sommerdörfer der Sherpa.", "type": "text"}]}]}, "question": "Was sind die Highlights des Gokyo Seen Treks?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Der Gokyo Ri mit 5.357 m an Tag 8. Du schläfst nie höher als im Dorf Gokyo auf 4.790 m.", "type": "text"}]}]}, "question": "Was ist der höchste Punkt des Treks?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Gokyo ist ruhiger und ein paar Tage kürzer, dafür hast du die Seen und vom Gokyo Ri einen weiteren Blick auf den Everest. Das Basislager ist der Klassiker und bringt dich bis an den Fuß des Bergs. Wer gut in Form ist, verbindet beides über den Cho La.", "type": "text"}]}]}, "question": "Gokyo-Seen oder Everest Base Camp?"}], "title": "Allgemeine Informationen"}, {"icon": "nordic_walking", "items": [{"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Unser Reiseverlauf dauert 12 Tage ab Kathmandu, davon 10 Tage auf dem Trail. Plane ein bis zwei Reservetage für Verspätungen beim Lukla-Flug ein.", "type": "text"}]}]}, "question": "Wie lange dauert der Gokyo Seen Trek?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Ab Kathmandu. In der Hauptsaison im Frühling und Herbst starten die meisten Flüge aber in Ramechhap (Manthali), 3–4 Std. Fahrt von Kathmandu, mit sehr frühem Aufbruch. Den Transfer organisieren wir.", "type": "text"}]}]}, "question": "Wo starten die Flüge nach Lukla?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Ja. Von Gokyo kannst du über den Cho La (5.420 m) nach Dzongla und Lobuche gehen und weiter zum Basislager und auf den Kala Patthar. Rechne mit etwa 16–18 Tagen und etwas Höhenerfahrung.", "type": "text"}]}]}, "question": "Kann ich Gokyo mit dem Everest Base Camp verbinden?"}], "title": "Reiseverlauf und Flüge"}, {"icon": "fitness_center", "items": [{"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Anspruchsvoll, Stufe 4 von 5, vor allem wegen der Höhe. Geklettert wird nicht, und die Etappen oberhalb von Namche sind kurz, damit du dich gut akklimatisieren kannst.", "type": "text"}]}]}, "question": "Wie schwer ist der Gokyo Seen Trek?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Bergwanderungen mit beladenem Tagesrucksack, Treppensteigen und regelmäßiges Ausdauertraining in den 8–12 Wochen vor der Reise.", "type": "text"}]}]}, "question": "Wie sollte ich trainieren?"}], "title": "Schwierigkeit und Fitness"}, {"icon": "medical_services", "items": [{"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Ein Ruhetag in Namche, kurze Etappen oberhalb von Dole, zweimal täglich Sauerstoff- und Pulsmessung, viel trinken und bei ernsten Symptomen sofort absteigen.", "type": "text"}]}]}, "question": "Wie beugt ihr der Höhenkrankheit vor?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Dein Guide hat ein Erste-Hilfe-Set und ein Pulsoximeter dabei. Falls nötig, organisiert unser Büro in Kathmandu mit deiner Versicherung eine Evakuierung per Hubschrauber.", "type": "text"}]}]}, "question": "Was passiert im Notfall?"}], "title": "Höhe und Gesundheit"}]$de$::jsonb, name = $de$Gokyo Seen Trek$de$, summary = $de$Türkisblaue Gletscherseen und der Blick vom Gokyo Ri auf vier Achttausender, abseits des belebtesten Trails.$de$, activity = $de$Trekking / Wandern$de$, category = $de$Ruhigerer Trek in großer Höhe$de$, excluded = $de$[{"text": "bestellst du frei von der Karte (etwa 30–40 USD am Tag; die Preise steigen mit der Höhe).", "title": "Mahlzeiten auf dem Trek"}, {"text": "Flüge nach Kathmandu und zurück.", "title": "Internationale Flüge"}, {"text": "Pflicht, mit Deckung für Hubschrauberrettung bis 6.000 m.", "title": "Reiseversicherung"}, {"text": "bei der Ankunft am Flughafen.", "title": "Touristenvisum für Nepal"}, {"text": "warme Duschen, Akkuladen und WLAN.", "title": "Extras in den Lodges"}]$de$::jsonb, headline = $de$Gokyo Seen Trek in 12 Tagen (Reiseverlauf, Kosten, kompletter Ratgeber)$de$, included = $de$[{"text": "Kathmandu (oder Ramechhap) – Lukla – Kathmandu, bei Bedarf mit Transfer nach Ramechhap.", "title": "Inlandsflüge"}, {"text": "in Erster Hilfe geschult, versichert und fair bezahlt.", "title": "Lizenzierter Guide und Träger"}, {"text": "10 Nächte auf dem Trek und die erste Hotelnacht in Kathmandu.", "title": "Übernachtung in Teehäusern"}, {"text": "Genehmigung für den Sagarmatha-Nationalpark und lokale Genehmigung der Gemeinde Khumbu Pasang Lhamu.", "title": "Genehmigungen"}, {"text": "Pulsoximeter und Erste-Hilfe-Set, mit Sauerstoffmessung zweimal am Tag.", "title": "Sicherheitsausrüstung"}, {"text": "bei Ankunft und Abreise in Kathmandu.", "title": "Flughafentransfers"}]$de$::jsonb, days_note = $de$Rückkehr nach Kathmandu$de$, seo_title = $de$Gokyo Trek 12 Tage: Reiseverlauf & Kosten ab 1.090 €$de$, transport = $de$Flug nach Lukla$de$, card_badge = $de$Ruhigeres Everest-Gebiet$de$, highlights = $de$[{"text": "Vier Achttausender auf einen Blick: Everest, Lhotse, Makalu und Cho Oyu über den Seen.", "title": "Sonnenaufgang auf dem Gokyo Ri (5.357 m)"}, {"text": "Eine Kette von Gletscherseen auf rund 4.700–4.800 m, Hindus und Buddhisten heilig.", "title": "Die türkisblauen Gokyo-Seen"}, {"text": "Du wanderst neben dem längsten Gletscher Nepals, einem gewaltigen Strom aus Eis und Geröll unterhalb des Cho Oyu.", "title": "Ngozumpa-Gletscher"}, {"text": "Weit weniger Trekker als auf der Route zum Basislager, mit kleinen Lodges in Dole und Machhermo.", "title": "Ruhigere Wege"}, {"text": "Die Hauptstadt der Sherpa und ein traditionelles Dorf an deinem Ruhetag, mit Everest-Blick oberhalb des Orts.", "title": "Namche Bazar und Khumjung"}, {"text": "Ein kurzer, spektakulärer Flug mitten ins Herz des Khumbu.", "title": "Bergflug nach Lukla"}]$de$::jsonb, know_intro = $de$Das Wichtigste von unseren einheimischen Trekkingleitern.$de$, route_line = $de$Routenüberblick Gokyo Seen Trek (Lukla – Namche Bazar – Gokyo)$de$, faq_heading = $de$Häufige Fragen zum Gokyo Seen Trek$de$, guide_ratio = $de$1 : 4 + Träger$de$, know_topics = $de$[{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Herbst (Oktober bis November):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " der klarste Himmel des Jahres und die zuverlässigsten Flüge nach Lukla.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Frühling (März bis Mai):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " wärmere Tage und blühende Rhododendren zwischen Namche und Dole.", "type": "text"}]}]}, "icon": "wb_twilight", "note": "Der Winter (Dez.–Feb.) ist klar, aber die Seen frieren zu und die Nächte sind sehr kalt. Der Monsun (Juni–Sept.) bringt Wolken und häufige Flugausfälle.", "title": "Beste Reisezeit und Wetterfenster", "photoId": null, "videoId": null}, {"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Zimmer:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Zweibettzimmer mit Schaumstoffmatratzen; die Lodges in Gokyo liegen direkt am Seeufer.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Heizung und Duschen:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " abends heizt ein Ofen den Speiseraum; eine warme Dusche kostet ein paar Dollar.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "WLAN und Strom:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " in den meisten Lodges gibt es WLAN-Karten und Lademöglichkeiten gegen Gebühr; weiter oben ist der Solarstrom schwächer.", "type": "text"}]}]}, "icon": "cottage", "note": "", "title": "Teehäuser: Unterkunft und Ausstattung", "photoId": null, "videoId": null}, {"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Dal Bhat:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Reis, Linsensuppe, Gemüse und Pickles, mit kostenlosem Nachschlag.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Speisekarten unterwegs:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Knoblauchsuppe, Sherpa-Eintopf, Porridge, Nudeln, Pasta und Ingwertee.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Trinken:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " trink 3–4 Liter am Tag und bereite dein Wasser auf; verzichte auf Einwegplastik.", "type": "text"}]}]}, "icon": "soup_kitchen", "note": "", "title": "Essen, Ernährung und sicheres Wasser", "photoId": null, "videoId": null}, {"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Rettung:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " sollte es je nötig sein, organisiert unser Büro in Kathmandu mit deiner Versicherung die Evakuierung per Hubschrauber.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Unterwegs:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " dein Guide hat ein Erste-Hilfe-Set und ein Pulsoximeter dabei und kennt die nächsten Hubschrauberlandeplätze.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Versicherung:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " eine Reiseversicherung, die Evakuierungen bis 6.000 m abdeckt, ist für alle Trekker Pflicht.", "type": "text"}]}]}, "icon": "emergency", "note": "", "title": "Notfallplan und Hubschrauberevakuierung", "photoId": null, "videoId": null}]$de$::jsonb, seo_keyword = $de$Gokyo Trek$de$, guides_intro = $de$Lizenzierte Guides aus dem Khumbu und den Hügeln des Solu, in Wildnis-Erster-Hilfe geschult und ganz auf sichere Akklimatisierung bedacht.$de$, introduction = $de${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Der Gokyo Seen Trek, oft einfach Gokyo Trek genannt, führt dich ins ruhigere Tal westlich des Weges zum Everest Base Camp. Ab Namche Bazar steigt der Pfad am Dudh Koshi entlang zu den Sommerdörfern Dole und Machhermo und dann neben dem Ngozumpa-Gletscher, dem längsten Nepals, zu einer Kette türkisblauer Seen bei Gokyo (4.790 m).", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Oberhalb des Dorfes bietet der Gokyo Ri (5.357 m) einen der großartigsten Ausblicke im Himalaya: Everest, Lhotse, Makalu und Cho Oyu, vier der Achttausender der Erde, in einem einzigen Panorama. Der Trek ist eine kürzere, ruhigere Alternative zum Everest Base Camp, mit derselben Sherpa-Kultur und denselben Teehäusern.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Die Etappen sind kürzer als auf der Route zum Basislager, und wir planen einen Ruhetag in Namche ein, damit du in sicherem Tempo aufsteigst.", "type": "text"}]}]}$de$::jsonb, know_heading = $de$Gokyo Seen Trek: Reisezeit, Teehäuser und Höhe$de$, packing_line = $de${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Bewährte Ausrüstung für das Gokyo-Tal: von −15 °C in den Nächten an den Seen bis zu warmen, sonnigen Tagen unterhalb von Namche.", "type": "text"}]}]}$de$::jsonb, photo_badges = $de$[{"icon": "groups", "tone": "brand", "label": "Ruhiger als EBC"}, {"icon": "nordic_walking", "tone": "green", "label": "Mit Sherpa-Guide"}, {"icon": "landscape", "tone": "brand", "label": "Sonnenaufgang Gokyo Ri"}]$de$::jsonb, season_label = $de$März–Mai, Okt.–Nov.$de$, accommodation = $de$Teehaus und Hotel$de$, daily_walking = $de$4 bis 7 Stunden am Tag$de$, packing_intro = $de$Bewährte Ausrüstung für das Gokyo-Tal: von −15 °C in den Nächten an den Seen bis zu warmen, sonnigen Tagen unterhalb von Namche.$de$, pricing_intro = $de$Buche direkt bei unserem Team in Kathmandu, ohne Zwischenhändler. Jeder Trek ist privat, du wählst also dein eigenes Startdatum.$de$, similar_intro = $de$Treks, die wir mit dir planen und die einheimische Guides leiten.$de$, elevation_note = $de$Du schläfst nie höher als auf 4.790 m in Gokyo und steigst nur für eine Tageswanderung auf den Gipfel des Gokyo Ri.$de$, guides_heading = $de$Lerne deinen Trekking-Guide kennen$de$, packing_groups = $de$[{"icon": "apparel", "items": [{"text": "2–3 Ober- und Unterteile aus Merino oder Kunstfaser.", "title": "Funktionsunterwäsche"}, {"text": "eine warme Fleece- oder Softshelljacke.", "title": "Fleece als Mittelschicht"}, {"text": "ausgelegt für etwa −15 °C in Machhermo und Gokyo.", "title": "Daunenjacke"}, {"text": "Jacke und Hose gegen Wind und Schnee.", "title": "Wetterfeste Außenschicht"}], "title": "Kleidung und Zwiebelprinzip"}, {"icon": "footprint", "items": [{"text": "wasserdicht, eingelaufen, mit Knöchelstütze.", "title": "Trekkingschuhe"}, {"text": "leichte Turnschuhe oder Sandalen fürs Teehaus.", "title": "Hüttenschuhe"}, {"text": "4–5 Paar gepolsterte Trekkingsocken, dazu ein warmes Paar für die Nacht.", "title": "Socken"}, {"text": "praktisch für vereiste Wege am Gokyo Ri zu Beginn oder Ende der Saison.", "title": "Grödel"}], "title": "Schuhe und Fußpflege"}, {"icon": "backpack", "items": [{"text": "mit Regenhülle, für Kleidungsschichten, Wasser und Snacks.", "title": "Tagesrucksack (25–35 l)"}, {"text": "trägt dein Träger (max. 15 kg; bei den Lukla-Flügen ist das Gepäck begrenzt).", "title": "Reisetasche"}, {"text": "Komfortbereich bis −15 °C (kann in Kathmandu ausgeliehen werden).", "title": "Schlafsack"}, {"text": "für die Abstiege und den Sonnenaufgang am Gokyo Ri.", "title": "Trekkingstöcke und Stirnlampe"}], "title": "Ausrüstung und Gepäck"}, {"icon": "medical_services", "items": [{"text": "Tabletten oder ein UV-Stift, dazu zwei 1-l-Flaschen.", "title": "Wasseraufbereitung"}, {"text": "Blasenpflaster, Schmerzmittel, Elektrolytpulver und deine eigenen Medikamente.", "title": "Reiseapotheke"}, {"text": "Sonnencreme mit LSF 50, Lippenpflege und eine Sonnenbrille der Kategorie 3–4.", "title": "Sonnenschutz"}, {"text": "Feuchttücher, Handdesinfektion und ein schnell trocknendes Handtuch.", "title": "Hygiene"}], "title": "Gesundheit, Hygiene und Wasser"}]$de$::jsonb, protected_area = $de$Sagarmatha-Nationalpark$de$, itinerary_intro = $de${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Zwölf Tage von Kathmandu zu den Gokyo-Seen und zurück. Du fliegst nach Lukla, legst in Namche Bazar einen Ruhetag ein, steigst über Dole und Machhermo langsam nach Gokyo auf und stehst zum Sonnenaufgang auf dem Gokyo Ri, bevor es zurück durchs Tal hinuntergeht. Jede Nacht auf dem Trail verbringst du in einem familiengeführten Teehaus.", "type": "text"}]}]}$de$::jsonb, meal_trail_tips = $de$[{"text": "Reis, Linsen und Gemüsecurry, so viel du magst. Der beste Treibstoff in der Höhe.", "title": "„Dal-Bhat-Power“"}, {"text": "Fleisch wird ungekühlt hinaufgetragen, deshalb empfehlen wir oberhalb von Namche vegetarische Gerichte.", "title": "Weiter oben vegetarisch essen"}, {"text": "trink 3–4 Liter am Tag (Ingwer-Zitrone-Honig-Tee, Knoblauchsuppe, abgekochtes Wasser).", "title": "Viel trinken"}, {"text": "oberhalb von Namche gibt es keine Geldautomaten. Nimm genug nepalesische Rupien aus Kathmandu mit.", "title": "Bargeld ist König"}]$de$::jsonb, packing_heading = $de$Packliste für den Gokyo Seen Trek$de$, pricing_heading = $de$Gruppenpreise nach Teamgröße$de$, seo_description = $de$Privater Gokyo Trek in 12 Tagen mit Sherpa-Guide: türkisblaue Gokyo-Seen, Ngozumpa-Gletscher und Sonnenaufgang am Gokyo Ri (5.357 m), abseits der Massen.$de$, similar_heading = $de$Ähnliche Trekkingtouren in Nepal$de$, elevation_heading = $de$Route und Höhenprofil$de$, itinerary_heading = $de$Reiseverlauf Tag für Tag$de$, route_map_heading = $de$Routenkarte Gokyo Seen Trek$de$, suitability_intro = $de$Eine ehrliche Checkliste unserer Guides, damit du entscheiden kannst, ob der Gokyo Seen Trek zu deinen Zielen passt.$de$, highlights_heading = $de$Highlights des Gokyo Seen Treks und warum du ihn lieben wirst$de$, inclusions_heading = $de$Im Preis enthalten · Nicht enthalten$de$, suitability_points = $de$[{"text": "4 bis 7 Stunden Gehzeit am Tag mit leichtem Tagesrucksack. Gute Ausdauer für steile Abschnitte und einen langen Abstieg.", "title": "Körperliche Anforderungen und Fitness"}, {"text": "Du schläfst auf 4.790 m in Gokyo und steigst auf den 5.357 m hohen Gokyo Ri. Ein Ruhetag in Namche und kurze Etappen helfen dir dabei.", "title": "Höhe und Akklimatisierung"}, {"text": "Keine. Steinige Wege und etwas Moräne. In den Trekkingsaisons brauchst du weder Seile noch Steigeisen oder Kletterausrüstung.", "title": "Technisches Können"}, {"text": "Teehäuser mit Zweibettzimmern und warmen Speiseräumen. In Machhermo und Gokyo einfacher und kälter.", "title": "Komfort und Unterkunft"}, {"text": "Rechne mit kalten Nächten, frühem Aufstehen und möglichen Flugverspätungen in Lukla.", "title": "Mentale Belastbarkeit"}, {"text": "Bei Herz- oder Lungenerkrankungen oder schwerem Asthma sprich vor der Buchung eines so hohen Treks mit deinem Arzt.", "title": "Vorerkrankungen"}]$de$::jsonb, meal_teahouse_notes = $de$[{"text": "Frühstück und Abendessen gibt es dort, wo du übernachtest. Nur so können die Lodges die Zimmerpreise niedrig halten.", "title": "Teehaus-Regel"}, {"text": "bestell das Abendessen gegen 17 Uhr und leg die Frühstückszeit am Vorabend fest.", "title": "Früh bestellen"}, {"text": "Duschen, Akkuladen und WLAN kosten weiter oben jeweils ein paar Dollar.", "title": "Kleine Extras"}]$de$::jsonb, suitability_heading = $de$Ist dieser Trek etwas für dich?$de$ where trek_id = 'a745508e-dc80-429d-8dae-24114ddb52b0' and locale = 'de';
update public.trek_day_translations set title = $de$Ankunft in Kathmandu (1.400 m), Begrüßung und Reisebesprechung$de$, duration = $de$Ankunft$de$, subtitle = $de$Abholung am Flughafen · Ausrüstungscheck in Thamel$de$, description = $de${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Unser Team holt dich am Tribhuvan International Airport ab und bringt dich ins Hotel. Am Abend prüfen wir deine Ausrüstung, kümmern uns um die Genehmigungen und bestätigen deinen Flug nach Lukla.", "type": "text"}]}]}$de$::jsonb where day_id = 'e6c1e622-5688-442d-a771-685537fee2fa' and locale = 'de';
update public.trek_day_translations set title = $de$Flug nach Lukla (2.860 m) und Wanderung nach Phakding (2.610 m)$de$, duration = $de$3–4 Std.$de$, subtitle = $de$Bergflug · Tal des Dudh Koshi$de$, description = $de${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Ein früher Flug nach Lukla, ab Kathmandu oder in der Hauptsaison ab Ramechhap, danach eine kurze Wanderung am Fluss entlang hinunter nach Phakding.", "type": "text"}]}]}$de$::jsonb where day_id = '8058bd86-c7f0-4071-acad-7aa345370f82' and locale = 'de';
update public.trek_day_translations set place = $de$Namche Bazar$de$, title = $de$Von Phakding nach Namche Bazar (3.440 m)$de$, duration = $de$6–7 Std.$de$, subtitle = $de$Hillary-Brücke · Erster Blick auf den Everest$de$, description = $de${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Auf Hängebrücken geht es über den Fluss, bei Monjo betrittst du den Sagarmatha-Nationalpark, dann folgt der lange Aufstieg nach Namche Bazar.", "type": "text"}]}]}$de$::jsonb where day_id = 'ae1ff7f4-508b-43f1-a10c-fb1c00d42d3f' and locale = 'de';
update public.trek_day_translations set place = $de$Namche Bazar$de$, title = $de$Akklimatisierungstag in Namche, Wanderung zum Everest View Hotel (3.880 m)$de$, duration = $de$3–4 Std.$de$, subtitle = $de$Ruhetag · Dorf Khumjung$de$, description = $de${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Am Morgen eine Wanderung oberhalb des Orts mit Blick auf Everest und Ama Dablam und, wenn du dich fit fühlst, ein Abstecher nach Khumjung. Der Nachmittag in Namche ist frei.", "type": "text"}]}]}$de$::jsonb where day_id = '39110fec-73d0-477a-b2ba-3d189fbc0152' and locale = 'de';
update public.trek_day_translations set title = $de$Von Namche Bazar über den Mong La nach Dole (4.040 m)$de$, duration = $de$5–6 Std.$de$, subtitle = $de$Aussichtspunkt am Grat · Hinein ins Gokyo-Tal$de$, description = $de${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Aufstieg zum Grat des Mong La (3.975 m) mit der Ama Dablam im Rücken, Abstieg zum Fluss bei Phortse Tenga und durch Rhododendron- und Birkenwald hinauf nach Dole.", "type": "text"}]}]}$de$::jsonb where day_id = 'f33cd7f5-ca72-4754-bf72-757e632f11f3' and locale = 'de';
update public.trek_day_translations set title = $de$Von Dole nach Machhermo (4.470 m)$de$, duration = $de$4–5 Std.$de$, subtitle = $de$Kurzer Tag · Yakweiden$de$, description = $de${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Ein kurzer Aufstieg über die Baumgrenze, vorbei an sommerlichen Yakweiden nach Machhermo. Der Nachmittag gehört der Erholung, damit sich dein Körper vor den Seen an die Höhe gewöhnt.", "type": "text"}]}]}$de$::jsonb where day_id = 'e11fcd21-8c27-49ff-a102-3fa1d1c977ec' and locale = 'de';
update public.trek_day_translations set title = $de$Von Machhermo nach Gokyo (4.790 m)$de$, duration = $de$4–5 Std.$de$, subtitle = $de$Ngozumpa-Gletscher · Die ersten Seen$de$, description = $de${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Vorbei an Pangka und neben dem Ngozumpa-Gletscher hinauf zum ersten und zweiten See, dann weiter zum Dorf am Ufer des dritten Sees, des Dudh Pokhari.", "type": "text"}]}]}$de$::jsonb where day_id = '601bbf5f-478c-4bef-8f8b-5447f0130d03' and locale = 'de';
update public.trek_day_translations set title = $de$Sonnenaufgang auf dem Gokyo Ri (5.357 m), Nachmittag an den Seen$de$, duration = $de$4–6 Std.$de$, subtitle = $de$Der höchste Punkt des Treks · Vier Achttausender$de$, description = $de${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Früh am Morgen steigst du steil auf den Gokyo Ri und erlebst den Sonnenaufgang über Everest, Lhotse, Makalu und Cho Oyu hoch über den Seen. Am Nachmittag ruhst du dich aus oder wanderst Richtung vierter See. Zweite Nacht in Gokyo.", "type": "text"}]}]}$de$::jsonb where day_id = 'dac4bdbd-c4d0-4f1d-b051-55e865099d5f' and locale = 'de';
update public.trek_day_translations set title = $de$Von Gokyo nach Dole (4.040 m)$de$, duration = $de$5–6 Std.$de$, subtitle = $de$Langer Abstieg durchs Tal$de$, description = $de${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Zurück an den Seen vorbei und über Machhermo hinunter nach Dole: Du verlierst schnell an Höhe und schläfst wieder gut.", "type": "text"}]}]}$de$::jsonb where day_id = '2bbc6375-efa9-479c-8361-e7859116e058' and locale = 'de';
update public.trek_day_translations set place = $de$Namche Bazar$de$, title = $de$Von Dole nach Namche Bazar (3.440 m)$de$, duration = $de$5–6 Std.$de$, subtitle = $de$Zurück über den Mong La$de$, description = $de${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Hinunter nach Phortse Tenga, ein letzter Aufstieg zum Mong La und auf dem Panoramaweg zurück nach Namche, wo eine warme Dusche und etwas Süßes aus der Bäckerei warten.", "type": "text"}]}]}$de$::jsonb where day_id = '625b76f2-fb6b-48dd-b300-fe7932cfa032' and locale = 'de';
update public.trek_day_translations set title = $de$Von Namche Bazar nach Lukla (2.860 m)$de$, duration = $de$6–7 Std.$de$, subtitle = $de$Letzter Trekkingtag · Feiern mit deinem Team$de$, description = $de${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Die letzte Etappe führt hinunter zum Fluss und wieder hinauf nach Lukla, wo wir mit deinem Guide und den Trägern das Ende des Treks feiern.", "type": "text"}]}]}$de$::jsonb where day_id = '6997d60d-4a18-4dd0-82c2-a884074f964a' and locale = 'de';
update public.trek_day_translations set title = $de$Flug von Lukla nach Kathmandu (1.400 m), Ende der Reise$de$, duration = $de$35 Min. Flug$de$, subtitle = $de$Morgenflug · Reservetag für Verspätungen einplanen$de$, description = $de${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Ein früher Flug nach Kathmandu, in der Hauptsaison nach Ramechhap mit anschließender Fahrt. Wir empfehlen einen Reservetag in Kathmandu vor deinem Heimflug, falls das Wetter für Verspätungen sorgt.", "type": "text"}]}]}$de$::jsonb where day_id = 'c5c8ab35-726c-4e59-8c56-fdc8aaf776a5' and locale = 'de';
update public.trek_group_price_translations set team = $de$Privater Guide + privater Träger$de$, label = $de$1 Person (allein)$de$, short_label = $de$1 Pers.$de$ where price_id = '73dc20c3-0453-4b16-a308-6c4ebbf9d930' and locale = 'de';
update public.trek_group_price_translations set team = $de$Guide + 1 Träger$de$, label = $de$2 Personen$de$, short_label = $de$2 Pers.$de$ where price_id = 'a3d7ff24-4d4d-4632-8047-34dbfb1b644d' and locale = 'de';
update public.trek_group_price_translations set team = $de$Leitender Guide + Assistent + Träger$de$, label = $de$3–5 Personen$de$, short_label = $de$3–5 Pers.$de$ where price_id = '74647423-f80d-4a41-8f94-02b5ada51130' and locale = 'de';
update public.trek_group_price_translations set team = $de$Leitender Guide + 2 Assistenten + Träger$de$, label = $de$6–10 Personen$de$ where price_id = '704b68f4-eda2-41ad-86b6-447850b1f6ae' and locale = 'de';
update public.trek_group_price_translations set team = $de$Komplettes Trekking-Team$de$, label = $de$11+ Personen$de$, short_label = $de$11+ Pers.$de$ where price_id = '71a5d7c1-fd61-4202-b548-658e26aaca40' and locale = 'de';
update public.trek_translations set faqs = $de$[{"icon": "calendar_month", "items": [{"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Ja. An einem klaren Morgen stehen Everest, Makalu, Lhotse und Kanchenjunga am Horizont. Der Sonnenaufgang auf dem Gipfel ist der Höhepunkt des Treks.", "type": "text"}]}]}, "question": "Kann ich vom Pikey Peak wirklich den Everest sehen?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Der Pikey Peak mit 4.065 m an Tag 4. Du übernachtest nie höher als im Pikey Base Camp auf etwa 3.640 m.", "type": "text"}]}]}, "question": "Was ist der höchste Punkt des Treks?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Von Oktober bis Dezember hast du die klarste Sicht, von März bis Mai blühen die Rhododendren. Der Gipfel ist niedrig genug, um ihn auch im Winter zu besteigen. Im Monsun (Juni bis August) verstecken sich die Berge allerdings hinter Wolken.", "type": "text"}]}]}, "question": "Wann ist die beste Reisezeit?"}], "title": "Allgemeine Informationen"}, {"icon": "nordic_walking", "items": [{"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Unser Reiseverlauf dauert 7 Tage ab Kathmandu, davon 4 Tage auf dem Trail. Auf Wunsch hängst du den Dudh Kunda oder zusätzliche Nächte in Junbesi an.", "type": "text"}]}]}, "question": "Wie lange dauert der Pikey Peak Trek?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Mit dem Jeep von Kathmandu nach Dhap, etwa 8–10 Std. auf Bergstraßen. Der Trek endet in Phaplu. Von dort fliegst du zurück, wenn Flüge gehen, oder fährst mit dem Jeep.", "type": "text"}]}]}, "question": "Wie komme ich zum Startpunkt?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Der Pikey Peak liegt außerhalb der Nationalparks, du brauchst also keine Parkgenehmigung. An lokalen Kontrollposten wird manchmal nach einer TIMS-Karte gefragt. Wir haben alles Nötige dabei. In Nepal müssen ausländische Trekker mit einem lizenzierten Guide gehen, der über eine registrierte Agentur gebucht ist. Bei all unseren Treks ist einer dabei.", "type": "text"}]}]}, "question": "Brauche ich eine Genehmigung?"}], "title": "Reiseverlauf und Anreise"}, {"icon": "fitness_center", "items": [{"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Leicht, Stufe 2 von 5. Die Etappen dauern 4–6 Std., der höchste Punkt liegt auf 4.065 m. Am anstrengendsten ist der frühe Aufstieg zum Sonnenaufgang auf dem Gipfel.", "type": "text"}]}]}, "question": "Wie schwer ist der Pikey Peak Trek?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Das Risiko ist gering, weil du unter 3.700 m schläfst. Trotzdem gehen wir langsam, fragen jeden Tag nach, wie es dir geht, und steigen ab, wenn nötig. Dein Guide hat ein Erste-Hilfe-Set und ein Pulsoximeter dabei.", "type": "text"}]}]}, "question": "Ist Höhenkrankheit ein Risiko?"}], "title": "Schwierigkeit und Gesundheit"}]$de$::jsonb, summary = $de$Ein kurzer Trek durch Sherpa-Dörfer zu einem Sonnenaufgang mit Blick vom Everest bis zum Kanchenjunga, ganz ohne Lukla-Flug.$de$, activity = $de$Trekking / Wandern$de$, category = $de$Kurzer Aussichtstrek$de$, excluded = $de$[{"text": "du bestellst frei von der Karte (etwa USD 20–30 am Tag).", "title": "Mahlzeiten auf dem Trek"}, {"text": "Flüge nach und ab Kathmandu.", "title": "Internationale Flüge"}, {"text": "Pflicht, mit Deckung für Hubschrauberrettung.", "title": "Reiseversicherung"}, {"text": "bei der Ankunft am Flughafen.", "title": "Touristenvisum für Nepal"}, {"text": "heiße Duschen, Akkuladen und WLAN, wo vorhanden.", "title": "Extras in den Lodges"}]$de$::jsonb, headline = $de$Pikey Peak Trek 7 Tage (Reiseverlauf, Kosten, kompletter Guide)$de$, included = $de$[{"text": "Kathmandu – Dhap mit dem Jeep und Phaplu – Kathmandu mit Jeep oder Flug.", "title": "Transport vor Ort"}, {"text": "in Erster Hilfe geschult, versichert und fair bezahlt.", "title": "Lizenzierter Guide und Träger"}, {"text": "5 Nächte auf dem Trek und die erste Hotelnacht in Kathmandu.", "title": "Übernachtungen in Lodges"}, {"text": "alle Papiere, nach denen Kontrollposten auf der Route fragen.", "title": "Lokale Papiere"}, {"text": "Pulsoximeter und Erste-Hilfe-Set.", "title": "Sicherheitsausrüstung"}, {"text": "bei Ankunft und Abreise in Kathmandu.", "title": "Flughafentransfers"}]$de$::jsonb, days_note = $de$ab/bis Kathmandu$de$, seo_title = $de$Pikey Peak Trek 7 Tage: Reiseverlauf & Kosten ab 620 €$de$, transport = $de$Jeep nach Dhap$de$, card_badge = $de$Kurz und ruhig$de$, highlights = $de$[{"text": "Ein weites Panorama des östlichen Himalaya mit Everest und Makalu am Horizont.", "title": "Sonnenaufgang am Pikey Peak (4.065 m)"}, {"text": "Steinhäuser, Gebetsfahnen und familiengeführte Lodges in Dörfern abseits der vollen Wege.", "title": "Sherpa-Dörfer im Solu"}, {"text": "Ein hübsches Sherpa-Dorf und ganz in der Nähe eines der größten tibetisch-buddhistischen Klöster der Region.", "title": "Junbesi und Thupten Chholing"}, {"text": "Im Frühling färbt sich der Wald unterhalb des Pikey Base Camp rot und rosa.", "title": "Rhododendronwald"}, {"text": "Hin und zurück fährst du mit dem Jeep, Wetterverspätungen in Lukla betreffen dich also nie.", "title": "Kein Flug nötig"}, {"text": "Viel weniger Trekker als in der Everest-Region und Zeit für Gespräche mit einheimischen Familien.", "title": "Ruhige Wege"}]$de$::jsonb, know_intro = $de$Das Wichtigste von unseren einheimischen Trekkingleitern.$de$, route_line = $de$Überblick über die Route des Pikey Peak Treks (Dhap – Pikey Peak – Junbesi – Phaplu)$de$, faq_heading = $de$Häufige Fragen zum Pikey Peak Trek$de$, guide_ratio = $de$1 : 4 + Träger$de$, know_topics = $de$[{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Herbst und Frühwinter (Oktober bis Dezember):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " die klarste Sicht des Jahres und trockene Wege.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Frühling (März bis Mai):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " der Rhododendronwald blüht; die Sicht ist am frühen Tag am besten.", "type": "text"}]}]}, "icon": "wb_twilight", "note": "Der Winter (Jan.–Feb.) ist kalt, aber klar. Der Monsun (Juni–Sep.) bringt Regen, Blutegel und schlammige Straßen.", "title": "Beste Reisezeit und Wetterfenster", "photoId": null, "videoId": null}, {"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Zimmer:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " einfache Zweibettzimmer mit Decken; dein Schlafsack kommt obendrauf.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Heizung und Duschen:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " die Speiseräume sind abends warm; heiße Duschen sind einfach oder kommen aus dem Eimer.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Strom:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Akkus laden kannst du in den meisten Lodges, manchmal nur über Solarstrom.", "type": "text"}]}]}, "icon": "cottage", "note": "", "title": "Unterkunft und Ausstattung der Lodges", "photoId": null, "videoId": null}, {"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Dal Bhat:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Reis, Linsensuppe, Gemüse und Pickles, mit kostenlosem Nachschlag.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Lokale Speisekarten:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Sherpa-Eintopf, Kartoffeln, Nudeln, Porridge und tibetisches Brot.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Trinken:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " trink 3–4 Liter am Tag und bereite dein Wasser auf.", "type": "text"}]}]}, "icon": "soup_kitchen", "note": "", "title": "Essen, Ernährung und sicheres Wasser", "photoId": null, "videoId": null}, {"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Rettung:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " unser Büro in Kathmandu organisiert im Notfall die Hubschrauberevakuierung mit deiner Versicherung.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Auf dem Trail:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " dein Guide hat ein Erste-Hilfe-Set und ein Pulsoximeter dabei; in Phaplu gibt es ein Krankenhaus.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Versicherung:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " eine Reiseversicherung mit Deckung für Notfallevakuierung ist für alle Trekker Pflicht.", "type": "text"}]}]}, "icon": "emergency", "note": "", "title": "Notfallplan und Hubschrauberrettung", "photoId": null, "videoId": null}]$de$::jsonb, seo_keyword = $de$Pikey Peak Trek$de$, guides_intro = $de$Lizenzierte Guides aus den Hügeln von Solu und Khumbu, in Erster Hilfe geschult und gern bereit, dir unterwegs vom Leben der Sherpa zu erzählen.$de$, introduction = $de${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Der Pikey Peak Trek ist eine kurze Wanderung in den unteren Hügeln von Solu, südlich des Sagarmatha-Nationalparks, zu einem der weitesten Bergpanoramen Nepals. Vom Gipfel des Pikey Peak (4.065 m) siehst du bei Sonnenaufgang eine lange Kette von Himalaya-Gipfeln, vom Kanchenjunga im Osten über Makalu und Everest bis zu den Bergen des Rolwaling.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Du fährst von Kathmandu zum Ausgangspunkt, wanderst durch Yakweiden, Rhododendronwald und Sherpa-Dörfer und steigst über Junbesi ab, wo das Kloster Thupten Chholing einen kurzen Spaziergang talaufwärts liegt. Du wartest auf keinen Flug nach Lukla und triffst nur sehr wenige andere Trekker.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Die Etappen sind kurz und die Höhe ist moderat. Der Trek passt also gut zu Trekking-Neulingen, Familien und allen, die eine Woche Zeit haben.", "type": "text"}]}]}$de$::jsonb, know_heading = $de$Pikey Peak Trek Guide: Reisezeit, Lodges und Sicherheit$de$, packing_line = $de${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Bewährte Ausrüstung für die Hügel von Solu: von −5 °C in den Nächten im Pikey Base Camp bis zu warmen Tagen in den Dörfern.", "type": "text"}]}]}$de$::jsonb, photo_badges = $de$[{"icon": "route", "tone": "brand", "label": "Kein Lukla-Flug"}, {"icon": "nordic_walking", "tone": "green", "label": "Mit lokalem Guide"}, {"icon": "landscape", "tone": "brand", "label": "Blick auf den Everest"}]$de$::jsonb, season_label = $de$März–Mai, Okt.–Dez.$de$, start_finish = $de$Kathmandu / Dhap und Phaplu$de$, accommodation = $de$Lodge und Hotel$de$, daily_walking = $de$4 bis 6 Std. am Tag$de$, packing_intro = $de$Bewährte Ausrüstung für die Hügel von Solu: von −5 °C in den Nächten im Pikey Base Camp bis zu warmen Tagen in den Dörfern.$de$, pricing_intro = $de$Buch direkt bei unserem Team in Kathmandu, ohne Zwischenhändler. Jeder Trek ist privat, du wählst also deinen eigenen Starttermin.$de$, similar_intro = $de$Treks, die wir mit dir planen und die einheimische Guides leiten.$de$, elevation_note = $de$Du schläfst nie höher als etwa 3.640 m und steigst nur zum Sonnenaufgang auf den Gipfel.$de$, guides_heading = $de$Lerne deinen Trekking-Guide kennen$de$, packing_groups = $de$[{"icon": "apparel", "items": [{"text": "2–3 Oberteile und Hosen aus Merino oder Kunstfaser.", "title": "Funktionsunterwäsche"}, {"text": "ein warmes Fleece oder eine Softshelljacke.", "title": "Fleece als Mittelschicht"}, {"text": "für den Sonnenaufgang auf dem Gipfel und kalte Abende.", "title": "Daunenjacke"}, {"text": "Jacke und Hose gegen Regen und Wind.", "title": "Wetterfeste Außenschicht"}], "title": "Kleidung und Zwiebelprinzip"}, {"icon": "footprint", "items": [{"text": "wasserdicht, eingelaufen und knöchelhoch.", "title": "Trekkingschuhe"}, {"text": "leichte Turnschuhe oder Sandalen für die Lodge.", "title": "Hüttenschuhe"}, {"text": "4 Paar gepolsterte Trekkingsocken.", "title": "Socken"}, {"text": "praktisch gegen den Schlamm im Frühlingswald.", "title": "Gamaschen"}], "title": "Schuhe und Fußpflege"}, {"icon": "backpack", "items": [{"text": "mit Regenhülle, für Kleidungsschichten, Wasser und Snacks.", "title": "Tagesrucksack (25–35 l)"}, {"text": "trägt dein Träger (max. 15 kg).", "title": "Seesack"}, {"text": "Komfortbereich bis −10 °C (kannst du in Kathmandu leihen).", "title": "Schlafsack"}, {"text": "für die steilen Abstiege und den Aufstieg zum Sonnenaufgang.", "title": "Trekkingstöcke und Stirnlampe"}], "title": "Ausrüstung und Gepäck"}, {"icon": "medical_services", "items": [{"text": "Tabletten oder ein UV-Stift, dazu zwei 1-Liter-Flaschen.", "title": "Wasseraufbereitung"}, {"text": "Blasenpflaster, Schmerzmittel, Elektrolyte und Tabletten gegen Reiseübelkeit für die Straßen.", "title": "Reiseapotheke"}, {"text": "Sonnencreme mit LSF 50 und Lippenbalsam.", "title": "Sonnenschutz"}, {"text": "Feuchttücher, Händedesinfektion und ein schnell trocknendes Handtuch.", "title": "Hygiene"}], "title": "Gesundheit, Hygiene und Wasser"}]$de$::jsonb, itinerary_intro = $de${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Sieben Tage von Kathmandu bis auf den Gipfel des Pikey Peak und zurück. Du fährst nach Dhap, wanderst hinauf zum Pikey Base Camp, steigst zum Sonnenaufgang auf den Gipfel und gehst über Jase Bhanjyang und Junbesi hinunter nach Phaplu. Von dort fliegst oder fährst du zurück nach Kathmandu. Jede Nacht auf dem Trail verbringst du in einer familiengeführten Lodge.", "type": "text"}]}]}$de$::jsonb, meal_trail_tips = $de$[{"text": "Reis, Linsen und Gemüsecurry mit unbegrenztem Nachschlag. Der beste Treibstoff auf dem Trail.", "title": "„Dal-Bhat-Power“"}, {"text": "Sherpa-Eintopf, Kartoffeln und frischer Yakkäse stehen in den Lodges im Solu oft auf der Karte.", "title": "Probier die lokale Küche"}, {"text": "3–4 Liter am Tag (Ingwer-Zitronen-Honig-Tee, Knoblauchsuppe, abgekochtes Wasser).", "title": "Trink genug"}, {"text": "auf dem Trail gibt es keine Geldautomaten. Nimm genug nepalesische Rupien aus Kathmandu mit.", "title": "Bargeld ist König"}]$de$::jsonb, packing_heading = $de$Packliste für den Pikey Peak Trek$de$, pricing_heading = $de$Gruppenpreise nach Teamgröße$de$, seo_description = $de$Privater Pikey Peak Trek in 7 Tagen mit lokalem Guide: Sherpa-Dörfer, kein Lukla-Flug und Sonnenaufgang vom Everest bis zum Kanchenjunga auf 4.065 m.$de$, similar_heading = $de$Ähnliche Trekkingtouren in Nepal$de$, elevation_heading = $de$Route und Höhenprofil$de$, itinerary_heading = $de$Reiseverlauf Tag für Tag$de$, route_map_heading = $de$Routenkarte des Pikey Peak Treks$de$, suitability_intro = $de$Eine ehrliche Checkliste unserer Guides, damit du entscheiden kannst, ob der Pikey Peak Trek zu dir passt.$de$, highlights_heading = $de$Highlights des Pikey Peak Treks und warum du ihn lieben wirst$de$, inclusions_heading = $de$Inklusive · Nicht inklusive$de$, suitability_points = $de$[{"text": "4 bis 6 Std. Gehzeit am Tag mit leichtem Tagesrucksack. Eine normale Grundfitness reicht.", "title": "Körperliche Anforderungen und Fitness"}, {"text": "Du schläfst nie höher als etwa 3.640 m und steigst zum Sonnenaufgang auf 4.065 m. Geeignet für alle, die gesund sind.", "title": "Höhe und Akklimatisierung"}, {"text": "Keines. Dorfwege, Waldpfade und einige steile Stufen. Keine Kletterausrüstung.", "title": "Technisches Können"}, {"text": "Einfache, familiengeführte Lodges mit gemeinsamen Speiseräumen. Schlicht, aber warm und herzlich.", "title": "Komfort und Unterkunft"}, {"text": "Lange Jeepfahrten auf Bergstraßen am Anfang und am Ende und kalte Nächte im Pikey Base Camp.", "title": "Mentale Belastbarkeit"}, {"text": "Wenn du Herz- oder Lungenprobleme oder schweres Asthma hast, sprich vor der Buchung mit deinem Arzt.", "title": "Vorerkrankungen"}]$de$::jsonb, meal_teahouse_notes = $de$[{"text": "du frühstückst und isst zu Abend, wo du übernachtest. Deshalb halten die Lodges die Zimmerpreise niedrig.", "title": "Lodge-Regel"}, {"text": "kleine Lodges kochen frisch, sag dein Abendessen also gegen 17 Uhr an.", "title": "Früh bestellen"}, {"text": "weniger Auswahl als auf den vollen Wegen, aber frisch und sättigend.", "title": "Einfache Speisekarten"}]$de$::jsonb, suitability_heading = $de$Ist dieser Trek etwas für dich?$de$ where trek_id = '1cbf52ec-0af4-415f-8b94-4eed78b83805' and locale = 'de';
update public.trek_day_translations set title = $de$Ankunft in Kathmandu (1.400 m), Begrüßung und Briefing$de$, duration = $de$Ankunft$de$, subtitle = $de$Abholung am Flughafen · Ausrüstungscheck in Thamel$de$, description = $de${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Unser Team empfängt dich am Tribhuvan International Airport und bringt dich ins Hotel. Am Abend prüfen wir deine Ausrüstung und gehen mit dir die Route durch.", "type": "text"}]}]}$de$::jsonb where day_id = 'e06cd9d7-6648-4731-a928-8d4e889b7c87' and locale = 'de';
update public.trek_day_translations set title = $de$Fahrt von Kathmandu nach Dhap (etwa 2.900 m)$de$, duration = $de$8–10 Std. Fahrt$de$, subtitle = $de$Lange Bergstraße · In die Hügel von Solu$de$, description = $de${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Eine lange Fahrt nach Osten durch das Mittelland nach Dhap, dem Dorf am Ausgangspunkt des Treks am Rand der Region Solu.", "type": "text"}]}]}$de$::jsonb where day_id = 'db7a2c8f-ede6-4e1c-9d6a-7bed8decd2eb' and locale = 'de';
update public.trek_day_translations set title = $de$Von Dhap zum Pikey Base Camp (3.640 m)$de$, duration = $de$5–6 Std.$de$, subtitle = $de$Yakweiden · Rhododendronwald$de$, description = $de${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Durch Wald und offene Weiden geht es am Dorf Jhapre vorbei hinauf zu den Lodges im Pikey Base Camp unterhalb des Gipfelgrats.", "type": "text"}]}]}$de$::jsonb where day_id = '7fc4e340-ce56-4555-9257-3321fe194b1e' and locale = 'de';
update public.trek_day_translations set place = $de$Pikey Peak$de$, title = $de$Sonnenaufgang auf dem Pikey Peak (4.065 m), Wanderung nach Jase Bhanjyang (etwa 3.500 m)$de$, duration = $de$5–6 Std.$de$, subtitle = $de$Der höchste Punkt des Treks · Der Everest am Horizont$de$, description = $de${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Früher Aufstieg zum Gipfel für den Sonnenaufgang über Everest, Makalu und den Gipfeln dahinter. Zum Frühstück zurück ins Base Camp, dann über den Grat nach Jase Bhanjyang.", "type": "text"}]}]}$de$::jsonb where day_id = 'fca3dc5f-61ba-4a9a-a3f1-c2624e949e6a' and locale = 'de';
update public.trek_day_translations set title = $de$Von Jase Bhanjyang nach Junbesi (2.675 m)$de$, duration = $de$5–6 Std.$de$, subtitle = $de$Sherpa-Dorf · Kloster Thupten Chholing$de$, description = $de${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Durch den Wald hinunter nach Junbesi, einem Sherpa-Dorf mit einem alten Kloster. Wenn du noch Energie hast, wanderst du am Nachmittag talaufwärts nach Thupten Chholing.", "type": "text"}]}]}$de$::jsonb where day_id = '4b1e37fa-bff9-4160-bd2a-7cc80fd7ef19' and locale = 'de';
update public.trek_day_translations set title = $de$Von Junbesi nach Phaplu (2.413 m)$de$, duration = $de$5–6 Std.$de$, subtitle = $de$Letzter Trekkingtag · Feier mit deinem Team$de$, description = $de${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Über einen niedrigen Grat und durch Dörfer und Felder hinunter nach Phaplu, wo wir mit deinem Guide und den Trägern das Ende des Treks feiern.", "type": "text"}]}]}$de$::jsonb where day_id = 'df6c744f-319b-4732-ada0-00b1a2760d52' and locale = 'de';
update public.trek_day_translations set title = $de$Flug oder Fahrt von Phaplu nach Kathmandu (1.400 m), Ende der Reise$de$, duration = $de$30 Min. Flug$de$, subtitle = $de$Kurzer Flug oder lange Jeepfahrt$de$, description = $de${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Ein kurzer Flug ab Phaplu, wenn Flüge gehen, oder eine lange Rückfahrt mit dem Jeep. Was davon, bestätigen wir dir bei der Buchung.", "type": "text"}]}]}$de$::jsonb where day_id = 'f83974cc-118d-4d29-84db-dfeac0c3eb2f' and locale = 'de';
