-- Blogs: their texts and sections
update public.article_translations set facts = $de$[{"icon": "wb_sunny", "label": "Beste Monate", "value": "Okt.–Nov., März–Mai"}, {"icon": "water_drop", "label": "Nasseste Monate", "value": "Juni–Aug. (Monsun)"}, {"icon": "wb_twilight", "label": "Kälteste Nächte", "value": "Dez.–Feb., unter −20 °C"}, {"icon": "altitude", "label": "Höchster Punkt", "value": "Kala Patthar, 5.545 m"}]$de$::jsonb, intro = $de$Klarer Herbsthimmel, blühende Rhododendren oder einsame Winterwege? Ein Guide aus dem Khumbu erklärt dir, wie jeder Monat auf dem Weg zum Everest Base Camp wirklich ist – und wann die beste Reisezeit für dich ist.$de$, title = $de$Beste Reisezeit für das Everest Base Camp: Monat für Monat$de$, card_text = $de$Was dich im Khumbu jeden Monat erwartet – vom klaren Oktoberhimmel bis zum stillen, eisigen Januar.$de$, cover_alt = $de$Everest und Nuptse über dem Khumbu-Gletscher an einem klaren Tag$de$, seo_title = $de$Beste Reisezeit Everest Base Camp: Monat für Monat$de$, month_notes = $de$[{"crowds": "very-low", "onTheTrail": "Sehr kalt und klar. Einige hoch gelegene Lodges schließen; nachts in Gorak Shep weit unter dem Gefrierpunkt."}, {"crowds": "low", "onTheTrail": "Noch kalt, die Tage werden langsam wärmer. Weiter oben ist Schnee möglich."}, {"crowds": "medium", "onTheTrail": "Wärmere Tage, weiter unten beginnen die Rhododendren zu blühen. Morgens gute Sicht."}, {"crowds": "busiest", "onTheTrail": "Milde Tage, blühende Wälder, Expeditionszelte am Base Camp. Nachmittags Wolken."}, {"crowds": "busy", "onTheTrail": "Der wärmste Monat in der Höhe und Höhepunkt der Bergsteigersaison. Ende Mai mehr Dunst und Wolken."}, {"crowds": "very-low", "onTheTrail": "Der Monsun kommt: Regen weiter unten, Wolken über den Gipfeln, viele gestrichene Flüge."}, {"crowds": "very-low", "onTheTrail": "Der nasseste Monat. Blutegel unterhalb von Namche, selten Sicht, Lukla-Flüge unzuverlässig."}, {"crowds": "very-low", "onTheTrail": "Immer noch Monsun. Grüne Täler, aber nasse Wege und wenige klare Morgen."}, {"crowds": "medium", "onTheTrail": "Der Regen lässt im Lauf des Monats nach. Ende September kann es herrlich grün sein."}, {"crowds": "busiest", "onTheTrail": "Glasklarer Himmel und stabiles Wetter. Der beliebteste Monat des Jahres."}, {"crowds": "busy", "onTheTrail": "Klar und trocken, kältere Nächte, etwas ruhiger als im Oktober."}, {"crowds": "low", "onTheTrail": "Kalt, klar und ruhig. Gestochen scharfe Sicht, wenn du für eisige Nächte gerüstet bist."}]$de$::jsonb, seo_keyword = $de$beste Reisezeit Everest Base Camp$de$, updated_line = $de$Aktualisiert für die Saison 2026/2027$de$, highlight_tag = $de$Ideal: Okt.–Nov. & März–Mai$de$, seo_description = $de$Beste Reisezeit Everest Base Camp: Ein Guide aus dem Khumbu über jeden Monat – klarer Oktoberhimmel, Frühlingsblüte, Winterkälte und Monsun.$de$ where article_id = '751b2de2-ffd2-4b05-8b33-bbbb4c4a594e' and locale = 'de';
update public.article_section_translations set content = $de${"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Oktober und November", "type": "text", "marks": [{"type": "bold"}]}, {"text": " bringen den klarsten Himmel und die zuverlässigsten Flüge nach Lukla. ", "type": "text"}, {"text": "März bis Mai", "type": "text", "marks": [{"type": "bold"}]}, {"text": " ist wärmer, mit blühenden Rhododendren weiter unten und Expeditionszelten am Base Camp. Der Dezember ist eine gute, ruhige Wahl, wenn du sehr kalte Nächte nicht scheust. Juni bis August ist Monsunzeit, davon raten wir ab.", "type": "text"}]}]}}$de$::jsonb where section_id = 'c25d2062-f74a-4d60-af20-dae5b9c5956a' and locale = 'de';
update public.article_section_translations set content = $de${"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Ich bin in Khumjung aufgewachsen, unterhalb der Ama Dablam, und bin in jedem Monat des Jahres zum Everest Base Camp gewandert. Der Weg ist immer derselbe, das Erlebnis nicht. Der Monat, den du wählst, entscheidet, wie klar die Berge sind, wie kalt deine Nächte werden, wie voll die Teehäuser sind und vor allem, ob dein Flug nach Lukla pünktlich startet. Hier erfährst du, wie jede Jahreszeit wirklich ist und wie du die beste Reisezeit für deinen Everest Base Camp Trek findest.", "type": "text"}]}]}}$de$::jsonb where section_id = 'ccc2da6b-be1b-4d54-8ad3-3975a3819a1d' and locale = 'de';
update public.article_section_translations set content = $de${"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Wenn der Monsun die Luft reingewaschen hat, bringt der Herbst das zuverlässigste Bergwetter des Jahres. Die Morgen sind meist wolkenlos, und vom Kala Patthar siehst du Everest, Nuptse und Pumori gestochen scharf vor tiefblauem Himmel. Auf dem unteren Weg wanderst du tagsüber angenehm im T-Shirt, während die Nächte oberhalb von Dingboche weit unter den Gefrierpunkt fallen.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Im Oktober ist im Khumbu am meisten los. Die Teehäuser in Namche, Dingboche und Lobuche füllen sich, deshalb buchen wir die Zimmer im Voraus und gehen früh los, damit es auf dem Weg ruhig bleibt. Der November ist etwas kälter und spürbar ruhiger, für viele unserer Guides ist er der schönste Monat überhaupt.", "type": "text"}]}]}, "heading": "Herbst (Oktober–November): die klarste Sicht", "tocLabel": "Herbst"}$de$::jsonb where section_id = '01b4592d-d8a8-4673-bcbd-e4626d889807' and locale = 'de';
update public.article_section_translations set content = $de${"heading": "Everest Base Camp Monat für Monat"}$de$::jsonb where section_id = 'e293ab93-8daf-4c57-aecf-562e31a6cf5c' and locale = 'de';
update public.article_section_translations set content = $de${"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Der Frühling ist die zweite große Saison. Die Tage sind wärmer als im Herbst, der Rhododendronwald unterhalb von Tengboche färbt sich rot und rosa, und im April und Mai entstehen die Expeditionslager am Base Camp. Die gelben Zelte der Bergsteigerteams neben dem Khumbu-Eisbruch vergessen viele Trekker ihr Leben lang nicht.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Der Preis dafür ist die Sicht. Die Morgen sind oft klar, aber nach dem Mittagessen ziehen Wolken auf, und gegen Ende Mai wird die Luft dunstiger. Im März kann es weiter oben noch kalt und verschneit sein. Er passt zu allen, die ruhige Wege mögen und denen ein frostiger Morgen nichts ausmacht.", "type": "text"}]}]}, "heading": "Frühling (März–Mai): wärmere Tage und Bergsteigersaison", "tocLabel": "Frühling"}$de$::jsonb where section_id = 'e366c2b2-7e74-4637-ad6e-115d16cf7599' and locale = 'de';
update public.article_section_translations set content = $de${"text": "Geh im Frühling spätestens um 7 Uhr los. Die beste Sicht hast du vor 10 Uhr, am Nachmittag ziehen die Wolken oft das Tal herauf. Wer früh startet, bekommt außerdem das wärmste Zimmer im nächsten Teehaus."}$de$::jsonb where section_id = '24fb68c2-5d3d-4ea5-b2de-69b78afe43fc' and locale = 'de';
update public.article_section_translations set content = $de${"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Im Winter ist der Himmel über dem Khumbu oft makellos klar, und auf dem Weg ist es so ruhig wie sonst nie im Jahr. Besonders der Dezember kann wunderschön sein: beständiges Wetter, klare Sicht und Teehausbesitzer, die Zeit zum Plaudern haben.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Es ist aber auch richtig kalt. Nachts fällt das Thermometer in Gorak Shep unter −20 °C, Wasserflaschen frieren im Zimmer ein, und einige höher gelegene Lodges schließen für die Saison. Nach einem Sturm kann Schnee den Weg zwischen Lobuche und Gorak Shep bedecken. Mit einer guten Daunenjacke, einem Schlafsack bis etwa −20 °C und etwas Flexibilität ist der Winter eine lohnende Reisezeit.", "type": "text"}]}]}, "heading": "Winter (Dezember–Februar): ruhig und kalt", "tocLabel": "Winter"}$de$::jsonb where section_id = '5ee21b9a-2456-4747-90cc-1edc2e168cea' and locale = 'de';
update public.article_section_translations set content = $de${"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Von Juni bis August bringt der Monsun täglich Regen, Wolken über den Gipfeln und häufige Flugausfälle in Lukla. Die unteren Wege sind schlammig, unterhalb von Namche gibt es Blutegel. Im Sommer führen wir Everest-Treks nur für erfahrene Trekker mit Puffertagen durch.", "type": "text"}]}]}}$de$::jsonb where section_id = '076bf4fd-ff3d-4fe0-80f6-ac3d1a0b74c1' and locale = 'de';
update public.article_section_translations set content = $de${"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Der Khumbu liegt höher und trockener als große Teile Nepals, doch der Monsun erreicht ihn trotzdem. Die meisten Tage beginnen bewölkt, nachmittags regnet es, und die hohen Gipfel verstecken sich oft tagelang. Das größere Problem ist der Flug: Lukla braucht klares Wetter in einem engen Tal, und im Sommer sind Verspätungen von mehreren Tagen normal.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Der September ist ein Monat des Wandels. Meist lässt der Regen in der zweiten Monatshälfte nach, die Täler sind grün, und vor dem Andrang im Oktober ist der Weg noch ruhig. Wenn du nur im September reisen kannst, nimm die letzte Woche und plane zwei Puffertage für den Flug ein.", "type": "text"}]}]}, "heading": "Der Monsun (Juni–September)", "tocLabel": "Monsun"}$de$::jsonb where section_id = 'f91a423e-eb03-446f-a093-bdf76321ea21' and locale = 'de';
update public.article_section_translations set content = $de${"alt": "Der spitze Schneegipfel der Ama Dablam über einem braunen Hochtal", "caption": "Die Ama Dablam, der Berg, der über den Weg von Tengboche nach Dingboche wacht."}$de$::jsonb where section_id = '66332c84-0636-4b2d-bf05-187dd8444527' and locale = 'de';
update public.article_section_translations set content = $de${"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Den einen besten Monat gibt es nicht, wohl aber den besten Monat für dich. Diese Übersicht hilft dir:", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Für die klarste Sicht:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Mitte Oktober bis Ende November.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Für wärmere Tage und Blüten:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Ende März bis Anfang Mai.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Für die Expeditionslager am Base Camp:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " April oder Anfang Mai.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Für ruhige Wege:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Anfang Dezember oder März, mit warmer Ausrüstung.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Wenn deine Reisedaten im Sommer feststehen:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Wähle lieber einen niedrigeren Trek und heb dir den Khumbu für den Herbst auf.", "type": "text"}]}]}]}, {"type": "paragraph", "content": [{"text": "Egal, welchen Monat du wählst: Plane am Ende deiner Reise ein oder zwei Puffertage ein. Das Bergwetter richtet sich nicht nach deinem Flugticket.", "type": "text"}]}]}, "heading": "So findest du deinen Monat", "tocLabel": "Monat wählen"}$de$::jsonb where section_id = 'da21f50a-ea57-4ccb-99ee-e993ab530453' and locale = 'de';
update public.article_section_translations set content = $de${"items": [{"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Oktober und November bringen den klarsten Himmel und die zuverlässigsten Flüge. Im Frühling ist der April am besten, mit warmen Tagen und der Bergsteigersaison am Base Camp.", "type": "text"}]}]}, "question": "Welcher Monat ist der beste für den Everest Base Camp Trek?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Ja. Von Dezember bis Februar ist es klar und ruhig, aber sehr kalt, mit Nächten unter −20 °C in Gorak Shep. Du brauchst warme Ausrüstung und etwas Flexibilität, falls Schnee fällt.", "type": "text"}]}]}, "question": "Kann ich im Winter zum Everest Base Camp wandern?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Es ist die schwierigste Zeit. Regen, Wolken und häufige Verspätungen der Lukla-Flüge machen Juni bis August unzuverlässig. Wenn du unbedingt dann gehen musst, plane zusätzliche Tage ein und rechne mit wenig Bergsicht.", "type": "text"}]}]}, "question": "Ist der Monsun eine schlechte Zeit für das Everest Base Camp?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Im Oktober ist am meisten los, danach im April. Wir buchen die Teehäuser im Voraus und gehen früh los, um dem Gedränge auf dem Weg auszuweichen.", "type": "text"}]}]}, "question": "Wann ist am Everest Base Camp am meisten los?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Etwa von Mitte April bis Ende Mai, wenn sich die Expeditionsteams auf die Besteigung des Everest vorbereiten. Außerhalb dieser Wochen ist das Base Camp ein stilles Feld aus Fels und Eis.", "type": "text"}]}]}, "question": "Wann sehe ich die Zelte der Bergsteiger am Base Camp?"}]}$de$::jsonb where section_id = 'e9659b19-bce2-401c-9340-19d189d9f08f' and locale = 'de';
update public.article_section_translations set content = $de${"heading": "Du weißt nicht, welcher Monat zu dir passt?", "message": "Hallo! Ich überlege, den Everest Base Camp Trek zu machen, und hätte gern euren Rat, welcher Monat für meine Reisedaten am besten ist.", "buttonText": "Per WhatsApp nach Terminen fragen"}$de$::jsonb where section_id = '1a25d8f2-0db9-468c-8666-e645a1f693f8' and locale = 'de';
update public.article_translations set facts = $de$[{"icon": "altitude", "label": "Höchste Übernachtung", "value": "Gorak Shep, 5.164 m"}, {"icon": "calendar_month", "label": "Ruhetage", "value": "Namche und Dingboche"}, {"icon": "hiking", "label": "Goldene Regel", "value": "Mit Symptomen nie höher steigen"}]$de$::jsonb, intro = $de$Nicht die Fitness, sondern die Höhe ist die eigentliche Herausforderung auf dem Weg zum Everest Base Camp. Was Höhenkrankheit ist, welche Warnzeichen du kennen solltest und wie dich ein langsamer, gut geplanter Aufstieg schützt.$de$, title = $de$Höhenkrankheit am Everest Base Camp: So beugst du vor$de$, card_text = $de$Die Warnzeichen der Höhenkrankheit und wie dich ein langsamer Aufstieg im Khumbu schützt.$de$, cover_alt = $de$Der Khumbu-Gletscher und die umliegenden Gipfel vom Kala Patthar aus$de$, seo_title = $de$Höhenkrankheit Everest Base Camp: So beugst du vor$de$, seo_keyword = $de$Höhenkrankheit Everest$de$, updated_line = $de$Aktualisiert für die Saison 2026/2027$de$, highlight_tag = $de$Zwei Ruhetage eingeplant$de$, seo_description = $de$Höhenkrankheit Everest: So beugst du auf dem Everest Base Camp Trek vor. Warnzeichen, Ruhetage, tägliche Gewohnheiten und was unsere Guides im Notfall tun.$de$ where article_id = 'f8ee65fe-a60e-4bab-83a0-3adbf82ae8c7' and locale = 'de';
update public.article_section_translations set content = $de${"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Höhenkrankheit ist über 3.000 m häufig und kann jeden treffen, egal wie fit. Der beste Schutz ist ein ", "type": "text"}, {"text": "langsamer Aufstieg mit Ruhetagen", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", viel Wasser und eine einfache Regel: ", "type": "text"}, {"text": "mit Symptomen nie höher steigen", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Werden die Symptome schlimmer, steig ab.", "type": "text"}]}]}}$de$::jsonb where section_id = '9e89c4cd-c06c-46fb-8caf-a2bc1a0ab52d' and locale = 'de';
update public.article_section_translations set content = $de${"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Jede Saison planen wir Dutzende Everest-Treks, und die Frage, die wir am häufigsten hören, dreht sich nicht um Fitness oder Essen, sondern um die Höhe. Und das zu Recht. Der Weg zum Base Camp ist eher gleichmäßig als extrem, doch du schläfst mehrere Nächte über 4.000 m und erreichst auf dem Kala Patthar 5.545 m. Dieser Ratgeber zur Höhenkrankheit am Everest, geprüft von unserem erfahrensten Everest-Guide Ang Dorje Sherpa, erklärt, was dort oben in deinem Körper passiert und wie wir das Risiko gering halten. Er gibt allgemeine Hinweise und ersetzt keine ärztliche Beratung: Sprich vor der Reise mit deiner Ärztin oder deinem Arzt.", "type": "text"}]}]}}$de$::jsonb where section_id = 'f29dea48-6c15-44f6-b6e3-ecb59f75750c' and locale = 'de';
update public.article_section_translations set content = $de${"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Je höher du steigst, desto weniger Sauerstoff bekommst du mit jedem Atemzug. Dein Körper kann sich anpassen, indem er schneller atmet und mehr rote Blutkörperchen bildet, aber dafür braucht er Zeit. Steigst du schneller auf, als er sich umstellen kann, droht die akute Höhenkrankheit, meist AMS genannt (vom englischen „Acute Mountain Sickness“).", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "AMS hat nichts mit Kraft zu tun. Junge, fitte Trekker, die vorausstürmen, spüren sie oft zuerst, während langsamere Wanderer gut in Form ankommen. Sie beginnt meist 6–12 Std. nach dem Erreichen einer neuen Höhe. Deshalb zählt, wie hoch du schläfst, mehr als die Höhe, die du tagsüber erreichst.", "type": "text"}]}]}, "heading": "Was Höhenkrankheit ist", "tocLabel": "Was sie ist"}$de$::jsonb where section_id = '16a33e26-1c81-40a1-9b10-d759951a8322' and locale = 'de';
update public.article_section_translations set content = $de${"body": {"type": "doc", "content": [{"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Leichte AMS (häufig)", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Kopfschmerzen, oft schlimmer in der Nacht oder am Morgen", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Appetitlosigkeit oder Übelkeit", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Ungewöhnliche Müdigkeit und Schwindel", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Schlechter Schlaf", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Schwere Formen (selten, aber Notfälle)", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "HAPE", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", das Höhenlungenödem (Wasser in der Lunge): Atemnot sogar in Ruhe, feuchter Husten, völlige Kraftlosigkeit", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "HACE", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", das Höhenhirnödem (Schwellung des Gehirns): Verwirrtheit, Ungeschicklichkeit, Mühe, geradeaus zu gehen, ungewöhnliches Verhalten", "type": "text"}]}]}]}, {"type": "paragraph", "content": [{"text": "Leichte AMS geht mit Ruhe auf derselben Höhe meist vorbei. HAPE und HACE erfordern einen sofortigen Abstieg und medizinische Hilfe.", "type": "text"}]}]}, "heading": "Die Warnzeichen, die du kennen solltest", "tocLabel": "Warnzeichen"}$de$::jsonb where section_id = '751f70ba-e3e3-4cb0-b3b8-f48641943a7b' and locale = 'de';
update public.article_section_translations set content = $de${"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Mit Symptomen der Höhenkrankheit steigst du nie höher.", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Werden sie schlimmer oder bemerkst du Atemnot in Ruhe oder Verwirrtheit, steig sofort ab, auch nachts. Schon ein paar hundert Meter tiefer geht es oft schnell besser.", "type": "text"}]}]}}$de$::jsonb where section_id = 'abf2d778-7f08-48f0-a252-9a4b6674d827' and locale = 'de';
update public.article_section_translations set content = $de${"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Ein guter Reiseverlauf erledigt den Großteil der Arbeit. Unserer folgt den Empfehlungen der Höhenmedizin: Über 3.000 m die Schlafhöhe nur langsam steigern und alle paar Tage einen Ruhetag einlegen. Auf dem Everest Base Camp Trek heißt das zwei volle Akklimatisierungstage, einer in Namche Bazar (3.440 m) und einer in Dingboche (4.410 m).", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Auch an Ruhetagen wandern wir: hinauf zum Everest View Hotel oberhalb von Namche und ein Stück auf den Nangkartshang oberhalb von Dingboche. Hoch steigen und tiefer schlafen hilft deinem Körper bei der Anpassung, ein fauler Tag im Bett dagegen nicht.", "type": "text"}]}]}, "heading": "Wie unser Reiseverlauf hilft", "tocLabel": "Unser Reiseverlauf"}$de$::jsonb where section_id = '664f3c5f-9dae-4471-b727-61f4d2e6128f' and locale = 'de';
update public.article_section_translations set content = $de${"text": "Geh langsamer, als es sich natürlich anfühlt, besonders beim Aufstieg nach Namche. Wenn du beim Gehen noch reden kannst, stimmt dein Tempo. Wer das Base Camp erreicht, war an Tag 2 selten der Schnellste."}$de$::jsonb where section_id = '3600624b-bd3f-4754-9e53-67ba04a1e9ea' and locale = 'de';
update public.article_section_translations set content = $de${"items": ["Trink täglich 3–4 Liter Wasser, Tee oder Suppe", "Iss gut, auch ohne Hunger: Dal Bhat und Suppe sind ideal", "Verzichte oberhalb von Namche auf Alkohol", "Halte dich warm und schlaf in kalten Nächten mit Mütze", "Sag deinem Guide bei jedem Kopfschmerz Bescheid, auch wenn er leicht ist", "Lass deinen Guide morgens und abends Sauerstoffsättigung und Puls messen"], "heading": "Gewohnheiten, die jeden Tag helfen"}$de$::jsonb where section_id = 'cc47f928-c574-43fd-bed7-f376fd31aa24' and locale = 'de';
update public.article_section_translations set content = $de${"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Dein Guide hat ein Erste-Hilfe-Set und ein Pulsoximeter dabei und kontrolliert alle zweimal am Tag. Bei leichten Symptomen bleiben wir eine zusätzliche Nacht auf derselben Höhe, ruhen uns aus und trinken viel. Werden die Symptome schlimmer, steigen wir ab, meist nach Pheriche oder Namche, wo sich die meisten schnell erholen.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In der Hauptsaison betreibt die Himalayan Rescue Association in Pheriche eine Hilfsstation, besetzt mit ehrenamtlichen Ärztinnen und Ärzten. In ernsten Fällen organisiert unser Büro in Kathmandu zusammen mit deiner Versicherung eine Evakuierung per Hubschrauber. Deshalb ist für jeden Everest-Trek eine Reiseversicherung mit Hubschrauberrettung bis mindestens 5.600 m Pflicht.", "type": "text"}]}]}, "heading": "Was passiert, wenn jemand krank wird", "tocLabel": "Im Ernstfall"}$de$::jsonb where section_id = '9bc78014-bc58-45be-a0d1-883855f4e11c' and locale = 'de';
update public.article_section_translations set content = $de${"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Manche Trekker nehmen Acetazolamid (oft als Diamox verkauft), um die Akklimatisierung zu unterstützen. Es ist verschreibungspflichtig und hat Nebenwirkungen. Sprich deshalb mit deinem Arzt, ob es für dich infrage kommt, und nutze es nie, um schneller aufzusteigen, als der Reiseverlauf vorsieht.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Fitness schützt nicht vor Höhenkrankheit, aber sie macht die langen Tage leichter und lässt dir Kraft für die Anpassung. Ideal sind sechs bis acht Wochen mit Wanderungen, Treppensteigen und gleichmäßigem Ausdauertraining. Wenn du eine Herz- oder Lungenerkrankung hast, geh vor der Buchung zu deinem Arzt.", "type": "text"}]}]}, "heading": "Medikamente und Vorbereitung vor der Reise", "tocLabel": "Vor der Reise"}$de$::jsonb where section_id = 'f1b1d234-a6f4-48b2-a7fe-7748519a70dd' and locale = 'de';
update public.article_section_translations set content = $de${"alt": "Weiter Blick vom Kala Patthar über den Khumbu-Gletscher, Moränen und Schneegipfel", "caption": "Der Blick vom Kala Patthar (5.545 m), dem höchsten Punkt des Treks. Du steigst morgens von Gorak Shep aus hinauf."}$de$::jsonb where section_id = '503c9d45-3e5e-4ed0-80fe-6473a73b421f' and locale = 'de';
update public.article_section_translations set content = $de${"items": [{"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Sie kann ab etwa 2.500 m auftreten, am häufigsten aber über 3.000 m. Auf dem Everest Base Camp Trek merken viele die dünnere Luft zum ersten Mal in Namche Bazar (3.440 m).", "type": "text"}]}]}, "question": "Ab welcher Höhe beginnt die Höhenkrankheit?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Ja. Fitness schützt dich nicht, und gerade fitte Trekker, die zu schnell gehen, trifft es oft. Tempo und Ruhetage zählen viel mehr als Kraft.", "type": "text"}]}]}, "question": "Können auch fitte Menschen höhenkrank werden?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Unser Reiseverlauf über 14 Tage hat zwei: einen in Namche Bazar und einen in Dingboche. An beiden machst du eine kurze Wanderung nach oben und schläfst danach wieder auf derselben Höhe.", "type": "text"}]}]}, "question": "Wie viele Ruhetage braucht der Everest Base Camp Trek?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Sag deinem Guide Bescheid, ruh dich aus, trink Wasser und steig an diesem Tag nicht höher. Wird es mit Ruhe nicht besser oder sogar schlimmer, steigst du ab.", "type": "text"}]}]}, "question": "Was tue ich, wenn ich in der Höhe Kopfschmerzen bekomme?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Die Rettung organisiert unser Büro, bezahlt wird sie aber von deiner Reiseversicherung. Deine Police muss also eine Hubschrauberevakuierung beim Trekking bis mindestens 5.600 m abdecken.", "type": "text"}]}]}, "question": "Ist die Hubschrauberrettung inbegriffen?"}]}$de$::jsonb where section_id = '7bf1be2c-0e55-45c0-8e5b-d42383073923' and locale = 'de';
update public.article_section_translations set content = $de${"heading": "Fragen zur Höhe vor der Buchung?", "message": "Hallo! Ich plane den Everest Base Camp Trek und habe ein paar Fragen zur Höhe und zur Akklimatisierung.", "buttonText": "Unser Team per WhatsApp fragen"}$de$::jsonb where section_id = 'e179fcd0-f88b-4afc-8b2f-b4dd9b2468a8' and locale = 'de';
update public.article_translations set facts = $de$[{"icon": "route", "label": "Flugzeit", "value": "Rund 35 Min. ab Kathmandu"}, {"icon": "schedule", "label": "Fahrt nach Ramechhap", "value": "3–4 Std. ab Kathmandu"}, {"icon": "calendar_month", "label": "Puffertage", "value": "1–2 am Ende der Reise"}]$de$::jsonb, intro = $de$Jeder Everest Trek beginnt mit einem kurzen Bergflug nach Lukla. Wo er startet, warum es zu Verspätungen kommt, wie viel Gepäck du mitnehmen darfst und wie du deine Reise so planst, dass eine Verspätung sie nie verdirbt.$de$, title = $de$Lukla-Flug erklärt: Ramechhap, Verspätungen und was du einplanen solltest$de$, card_text = $de$Kathmandu oder Ramechhap, Wetterverspätungen und Gepäck: So funktioniert der Flug nach Lukla wirklich.$de$, cover_alt = $de$Die Häuser von Namche Bazar am Hang über dem Tal des Dudh Koshi$de$, seo_title = $de$Lukla Flug: Ramechhap, Verspätungen und Tipps$de$, seo_keyword = $de$Lukla Flug$de$, updated_line = $de$Aktualisiert für die Saison 2026/2027$de$, highlight_tag = $de$1–2 Puffertage einplanen$de$, seo_description = $de$Lukla Flug zum Everest Trek: Abflug in Kathmandu oder Ramechhap, warum das Wetter Verspätungen verursacht, Gepäcklimit und wie du Puffertage planst.$de$ where article_id = '52c0cf81-4567-4e64-b0e4-1145050bc614' and locale = 'de';
update public.article_section_translations set content = $de${"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Lukla-Flüge sind kleine Maschinen, die nur bei guter Sicht fliegen, deshalb ", "type": "text"}, {"text": "sind Verspätungen normal", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". In den vollen Hauptsaisons im Frühjahr und Herbst starten die meisten Flüge nicht in Kathmandu selbst, sondern in ", "type": "text"}, {"text": "Ramechhap (Manthali)", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", 3–4 Autostunden von Kathmandu entfernt. Plane ", "type": "text"}, {"text": "einen oder zwei Puffertage", "type": "text", "marks": [{"type": "bold"}]}, {"text": " am Ende deiner Reise ein, dann wird der Flug zum Teil des Abenteuers und nicht zum Problem.", "type": "text"}]}]}}$de$::jsonb where section_id = 'bd300281-ea90-402c-8a4c-ad682c94d23c' and locale = 'de';
update public.article_section_translations set content = $de${"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Ich organisiere Flüge, Genehmigungen und Transfers für jeden unserer Treks, und der Lukla-Flug ist der Teil einer Everest-Reise, der den meisten Menschen Sorgen macht. Das muss er nicht. Der Flug ist kurz und spektakulär, die Fluggesellschaften fliegen ihn an jedem Tag der Saison, und das Einzige, was du wirklich einplanen musst, ist das Wetter. So läuft es ab, von der Fahrt am frühen Morgen bis zu dem, was wir tun, wenn sich die Wolken einfach nicht heben.", "type": "text"}]}]}}$de$::jsonb where section_id = 'bd2dd9eb-49ec-44e2-984b-1ff3e173f2c2' and locale = 'de';
update public.article_section_translations set content = $de${"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Der Tenzing-Hillary-Flughafen in Lukla (2.860 m) hat eine kurze, geneigte Piste an einem Berghang, eingebaut in ein enges Tal. Nur kleine Maschinen mit erfahrenen Bergpiloten landen dort, und sie fliegen auf Sicht. Deshalb brauchen sie klares Wetter an beiden Enden und in den Tälern dazwischen.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Die Flüge starten morgens, wenn die Luft am ruhigsten ist und sich noch keine Wolken aufgebaut haben. Ist es morgens in Lukla bewölkt, warten die Flüge. Reißt die Wolkendecke nicht auf, werden sie gestrichen, und alle rücken auf die Liste des nächsten Tages.", "type": "text"}]}]}, "heading": "Warum Lukla anders ist", "tocLabel": "Warum Lukla"}$de$::jsonb where section_id = '927d3d65-a57e-4b30-8194-84dc00548ab3' and locale = 'de';
update public.article_section_translations set content = $de${"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Außerhalb der Hauptsaison starten die Flüge nach Lukla am Inlandsterminal in Kathmandu und dauern etwa 35 Minuten. Im Frühjahr und Herbst werden die meisten Lukla-Flüge zum Flughafen Manthali im Distrikt Ramechhap östlich der Hauptstadt verlegt, um die einzige Piste in Kathmandu zu entlasten.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Ab Ramechhap dauert der Flug nur etwa 20 Minuten, vorher fährst du aber 3–4 Stunden von Kathmandu aus. Um die ersten Flüge zu erwischen, heißt das meist: Abfahrt vom Hotel mitten in der Nacht. Wir organisieren den Transfer, und der Abflugort wird ein paar Tage vor deinem Flug bestätigt, sobald die Fluggesellschaften ihre Flugpläne bekannt geben.", "type": "text"}]}]}, "heading": "Kathmandu oder Ramechhap?", "tocLabel": "Abflugort"}$de$::jsonb where section_id = '611fd6c7-6c9f-41a5-b92f-fca4be0c02bd' and locale = 'de';
update public.article_section_translations set content = $de${"place": "Manthali Airport, Ramechhap, Nepal", "title": "Flughafen Manthali, Ramechhap"}$de$::jsonb where section_id = '7d6479b4-9d84-4871-b7b3-88751f7dbf29' and locale = 'de';
update public.article_section_translations set content = $de${"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Der Abflughafen hängt vom Flugplan der Airline und von der Saison ab. Ob du ab Kathmandu oder ab Ramechhap fliegst, bestätigen wir, sobald dein Flug gebucht ist. Den Transfer übernehmen wir in beiden Fällen.", "type": "text"}]}]}}$de$::jsonb where section_id = '44544bf4-4a3e-4c5c-86c5-6474ece93cff' and locale = 'de';
update public.article_section_translations set content = $de${"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Im Oktober und November starten die meisten Flüge pünktlich. Im Frühjahr sorgen Dunst und Wolken für mehr Wartezeit, und in der Monsunzeit sind Verspätungen von mehreren Tagen üblich. Der Rückflug von Lukla nach Kathmandu oder Ramechhap ist genauso oft betroffen wie der Hinflug.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Verspätet sich dein Flug, halten wir dich auf dem Laufenden, buchen dich auf den nächsten freien Flug um und passen den Trek bei Bedarf an. Deshalb liegen in jedem Everest-Reiseverlauf, den wir anbieten, die Puffertage am Ende, nach dem Trek. So verpasst du wegen einer Verspätung auf dem Hin- oder Rückweg nie deinen internationalen Flug.", "type": "text"}]}]}, "heading": "Verspätungen: was dich erwartet und was wir tun", "tocLabel": "Verspätungen"}$de$::jsonb where section_id = '2240474e-7d5a-41b3-ad05-608c3aa8efc6' and locale = 'de';
update public.article_section_translations set content = $de${"text": "Trag deine Wanderschuhe und pack deine warme Jacke, Wasser und Snacks ins Handgepäck. Landest du pünktlich in Lukla, läufst du direkt los nach Phakding; musst du warten, hast du es bequem."}$de$::jsonb where section_id = 'e9ccd195-28bd-4020-acd1-4ed49a8ff21b' and locale = 'de';
update public.article_section_translations set content = $de${"items": ["1–2 Puffertage am Ende der Reise in Kathmandu einplanen", "Leicht packen: Die Gepäckgrenze ist niedrig, etwa 15 kg inklusive Handgepäck (wir klären das mit der Airline)", "Reisepass und Genehmigungen ins Handgepäck", "Auf dem Flug Trekkingschuhe und warme Schichten tragen", "Snacks und Wasser für Wartetage griffbereit haben", "Prüfen, ob deine Reiseversicherung Reiseverspätungen abdeckt"], "heading": "Checkliste für den Lukla-Flug"}$de$::jsonb where section_id = 'e095831e-ee1e-4600-9c33-677739b5ca06' and locale = 'de';
update public.article_section_translations set content = $de${"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Damit bist du nicht allein, vielen unserer Trekker geht es so. Der Anflug auf Lukla ist kurz und dramatisch, die Piste taucht erst in der letzten Minute am Hang auf. Die Piloten fliegen diese Strecke an jedem Tag der Saison und starten nur, wenn das Wetter es zulässt. Setz dich auf dem Hinflug auf die linke Seite, um die hohen Gipfel zu sehen, richte den Blick auf die Berge statt auf die Piste, und denk daran: Wenn auf klares Wetter gewartet wird, funktioniert das System genau so, wie es soll.", "type": "text"}]}]}, "heading": "Wenn dir beim Fliegen mulmig ist", "tocLabel": "Flugangst"}$de$::jsonb where section_id = '822caac7-fe34-42dc-b7a7-fe4b9fdb6451' and locale = 'de';
update public.article_section_translations set content = $de${"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Hubschrauber können manchmal fliegen, wenn Flugzeuge am Boden bleiben, weil sie mit tieferen Wolken zurechtkommen. Fallen Flüge tagelang aus, teilen sich viele Trekker einen Hubschrauber nach oder ab Lukla. Das kostet mehr als das Flugzeug und hängt trotzdem vom Wetter ab, ist also eine Notlösung und keine Garantie. Falls es je nötig wird, organisieren wir ihn und sprechen die Kosten vorher mit dir ab.", "type": "text"}]}]}, "heading": "Gibt es eine Hubschrauber-Option?", "tocLabel": "Hubschrauber"}$de$::jsonb where section_id = '1f6faa1a-a647-4b0f-bf5f-99925e66f97c' and locale = 'de';
update public.article_section_translations set content = $de${"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Ja. Du kannst in den unteren Solukhumbu bis in die Gegend von Phaplu und Salleri fahren und in einigen zusätzlichen Tagen hinauf zum Everest-Weg wandern, auf der Route der ersten Expeditionen. Das dauert etwa eine Woche länger, dafür wanderst du durch Dörfer der Sherpa und Rai, die nur wenige Trekker zu sehen bekommen.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Wenn du vor allem den Everest sehen möchtest, ohne zu fliegen, schau dir den ", "type": "text"}, {"text": "Pikey Peak Trek", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/pikey-peak-trek"}}]}, {"text": " an: ein kurzer Trek mit Anreise per Auto und einem der weitesten Himalaya-Panoramen Nepals.", "type": "text"}]}]}, "heading": "Geht es auch ganz ohne Flug?", "tocLabel": "Ohne Flug"}$de$::jsonb where section_id = '8f69818a-f391-4297-b3b3-1bf5543c7bdc' and locale = 'de';
update public.article_section_translations set content = $de${"alt": "Die hufeisenförmig angeordneten Häuser von Namche Bazar von oben", "caption": "Namche Bazar, zwei Tagesetappen von Lukla entfernt, ist der richtige Ort, um eine reibungslose Ankunft zu feiern."}$de$::jsonb where section_id = 'b5a94224-8d63-40e3-9658-526a2d9b10b8' and locale = 'de';
update public.article_section_translations set content = $de${"items": [{"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Etwa 35 Minuten ab Kathmandu oder etwa 20 Minuten ab Ramechhap (Manthali). Nach Ramechhap fährst du vorher 3–4 Stunden von Kathmandu aus.", "type": "text"}]}]}, "question": "Wie lange dauert der Flug nach Lukla?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "In den vollen Hauptsaisons im Frühjahr und Herbst werden die meisten Lukla-Flüge zum Flughafen Manthali in Ramechhap verlegt, um den Verkehr auf der einzigen Piste in Kathmandu zu verringern. Außerhalb der Hauptsaison starten die Flüge meist in Kathmandu.", "type": "text"}]}]}, "question": "Warum starten Lukla-Flüge in Ramechhap?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Das hängt von der Jahreszeit ab. Der Herbst ist am zuverlässigsten; im Frühjahr wird wegen Wolken und Dunst öfter gewartet, und in der Monsunzeit sind Verspätungen von mehreren Tagen üblich. Plane immer Puffertage ein.", "type": "text"}]}]}, "question": "Wie oft verspäten sich Lukla-Flüge?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "In diesen kleinen Maschinen ist die Grenze niedrig, etwa 15 kg inklusive Handgepäck. Wir klären die genaue Freigepäckmenge mit der Airline, und zusätzliches Gepäck kannst du in deinem Hotel in Kathmandu lassen.", "type": "text"}]}]}, "question": "Wie viel Gepäck darf ich nach Lukla mitnehmen?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Wir buchen dich auf den nächsten freien Flug um und prüfen einen geteilten Hubschrauber, falls sich die Verspätung hinzieht. Genau dafür sind deine Puffertage in Kathmandu da.", "type": "text"}]}]}, "question": "Was passiert, wenn mein Rückflug von Lukla ausfällt?"}]}$de$::jsonb where section_id = 'dab5b678-6689-473e-be53-b56aab672f55' and locale = 'de';
update public.article_section_translations set content = $de${"heading": "Lass uns deinen Lukla-Flug planen", "message": "Hallo! Ich plane einen Everest Trek und hätte gern eure Hilfe bei den Lukla-Flügen und den Puffertagen.", "buttonText": "Flüge per WhatsApp anfragen"}$de$::jsonb where section_id = 'a33dd8f9-59f9-44e3-8a89-ad92987b83bf' and locale = 'de';
update public.article_translations set facts = $de$[{"icon": "altitude", "label": "Höchster Punkt", "value": "Pikey Peak, 4.065 m"}, {"icon": "calendar_month", "label": "Dauer", "value": "7 Tage ab Kathmandu"}, {"icon": "wb_sunny", "label": "Beste Monate", "value": "Okt.–Dez., März–Mai"}, {"icon": "description", "label": "Genehmigungen", "value": "Keine Nationalpark-Genehmigung"}]$de$::jsonb, intro = $de$Ich wollte den Everest sehen, hatte aber nur eine Woche und keine Lust, auf Lukla-Flüge zu warten. Der Pikey Peak schenkte mir einen Sonnenaufgang über dem ganzen Himalaya, Sherpa-Dörfer und stille Wege. So war es.$de$, title = $de$Pikey Peak Trek: Everest-Blick ohne Lukla-Flug$de$, card_text = $de$Eine Woche Trekking mit Anreise per Auto, Sonnenaufgang von Everest bis Kanchenjunga und ganz ohne Flug.$de$, cover_alt = $de$Erstes Licht über einer Kette von Himalaya-Gipfeln, gesehen vom Pikey Peak$de$, seo_title = $de$Pikey Peak Trek: Everest-Blick ohne Lukla-Flug$de$, seo_keyword = $de$Pikey Peak Trek$de$, updated_line = $de$Aktualisiert für die Saison 2026/2027$de$, highlight_tag = $de$Anreise per Auto, kein Flug$de$, seo_description = $de$Pikey Peak Trek aus erster Hand: eine Woche im Sherpa-Land, Sonnenaufgang von Everest bis Kanchenjunga und kein Warten auf den Lukla-Flug.$de$ where article_id = 'b039fd44-4cd3-45b0-9e2d-9144beeedbe8' and locale = 'de';
update public.article_section_translations set content = $de${"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Ich bin zum Everest Base Camp und rund um den Manaslu gewandert. Als Freunde mich nach einem kurzen Trek mit echtem Everest-Blick fragten, dachte ich deshalb, die Antwort wäre ein langer Flug und zwei Wochen Wandern. Dann schlug ein Guide in Kathmandu den Pikey Peak vor. Eine Woche später stand ich auf einem Gipfel über den Wolken, sah zu, wie die Sonne Everest und Makalu traf, und war auf dem Weg nach oben mehr Yaks als Trekkern begegnet. Das ist mein ehrlicher Bericht, geprüft von unserem Everest-Guide Ang Dorje Sherpa.", "type": "text"}]}]}}$de$::jsonb where section_id = 'eb7f394d-1ad9-4428-8ef2-848bb7dfa505' and locale = 'de';
update public.article_section_translations set content = $de${"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Der ", "type": "text"}, {"text": "Pikey Peak Trek", "type": "text", "marks": [{"type": "bold"}]}, {"text": " ist ein 7-tägiger Trek im unteren Solukhumbu, den du per Auto erreichst. Vom Gipfel (4.065 m) siehst du bei Sonnenaufgang eine lange Kette von Gipfeln, darunter ", "type": "text"}, {"text": "Everest, Makalu und Kanchenjunga", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Er ist niedriger, kürzer und ruhiger als der Everest Base Camp Trek, und es gibt ", "type": "text"}, {"text": "keinen Lukla-Flug", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", auf den du warten musst.", "type": "text"}]}]}}$de$::jsonb where section_id = '4c2b2981-9cb6-4347-b558-6d26de9e82f4' and locale = 'de';
update public.article_section_translations set content = $de${"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Der Pikey Peak ist ein Aussichtsberg in der unteren Solu-Region, südlich des Sagarmatha-Nationalparks. Er ist niedrig genug, um ihn in einer Woche zu besteigen, und hoch genug, um über den Himalaya zu blicken, vom Kanchenjunga im Osten bis zu den Gipfeln des Rolwaling im Westen.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Überzeugt hat mich die Anreise. Du fährst von Kathmandu bis zum Ausgangspunkt, die ganze Reise läuft also nach deinem Plan und nicht nach dem Wetter in Lukla. Wer nur eine Woche hat, Angst vor kleinen Flugzeugen oder einen knappen Rückflug, für den zählt das.", "type": "text"}]}]}, "heading": "Warum Pikey Peak", "tocLabel": "Warum Pikey Peak"}$de$::jsonb where section_id = '0de154a1-cd3e-4054-b21d-d404ebefe5af' and locale = 'de';
update public.article_section_translations set content = $de${"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Wir brachen im Dunkeln mit Stirnlampen vom Pikey Base Camp (3.640 m) auf und stiegen auf einem gleichmäßigen Pfad durch gefrorenes Gras und an Gebetsfahnen vorbei. Wir brauchten etwas mehr als eine Stunde. Oben färbte sich der Himmel langsam orange, und die Berge tauchten einer nach dem anderen auf: weit im Osten der Kanchenjunga, dann Makalu, Lhotse und Everest, dann der Numbur und die langen Grate im Westen.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Unter uns lagen die Täler des unteren Solukhumbu voller Wolken, aus denen Hügel wie Inseln ragten. So einen Ausblick behältst du noch Jahre im Kopf, und wir hatten ihn fast für uns allein.", "type": "text"}]}]}, "heading": "Sonnenaufgang auf dem Gipfel", "tocLabel": "Der Gipfel"}$de$::jsonb where section_id = '8edc7e25-0872-4f47-87cb-293a3051c816' and locale = 'de';
update public.article_section_translations set content = $de${"text": "Ich bin in Salleri aufgewachsen, ein paar Stunden vom Pikey Peak entfernt. Viele glauben, man braucht zwei Wochen, um den Everest zu sehen. Vom Pikey aus siehst du ihn mit einem heißen Tee in der Hand und niemandem vor dir."}$de$::jsonb where section_id = '38bf848f-9ff4-4920-99dc-94afdcdc45a8' and locale = 'de';
update public.article_section_translations set content = $de${"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Nach dem Gipfel führt der Weg hinunter durch Rhododendronwälder und Yakweiden nach Junbesi, einem schönen Sherpa-Dorf mit Steinhäusern und Feldern. In der Nähe liegt Thupten Chholing, ein großes tibetisch-buddhistisches Kloster, in dem Mönche und Nonnen lernen. Der stille Besuch am Morgen, bei dem uns unser Guide erklärte, was wir sahen, war einer der Höhepunkte meiner Woche.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Die Lodges hier werden von Familien geführt, die sich sichtlich über Trekker freuen. Wir aßen Dal Bhat am Ofen, spielten Karten mit den Kindern eines Lodge-Besitzers und erfuhren viel mehr über das Leben vor Ort als auf den volleren Wegen.", "type": "text"}]}]}, "heading": "Sherpa-Dörfer und Thupten Chholing", "tocLabel": "Dörfer"}$de$::jsonb where section_id = 'e72b74ba-5327-4ca0-a4c6-5003b3b10b15' and locale = 'de';
update public.article_section_translations set content = $de${"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Es sind zwei ganz verschiedene Reisen. Der Everest Base Camp Trek führt dich in rund zwei Wochen an den Fuß des Berges, zwischen Gletscher und Expeditionslager, mit Nächten über 5.000 m. Der Pikey Peak schenkt dir in einer Woche einen weiten Blick auf den Everest aus der Ferne, und du schläfst nie höher als etwa 3.640 m.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Wenn du zwei Wochen Zeit hast und gut in Form bist, ist das Everest Base Camp unvergesslich. Wenn du eine Woche hast, ruhige Wege suchst oder noch keine Erfahrung mit der Höhe hast, ist der Pikey Peak eine wunderbare Wahl.", "type": "text"}]}]}, "heading": "Pikey Peak oder Everest Base Camp?", "tocLabel": "Oder Everest?"}$de$::jsonb where section_id = '09ca8aaf-f408-4e93-91c7-dc7416751150' and locale = 'de';
update public.article_section_translations set content = $de${"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Der Pikey Peak ist ein guter erster Trek in Nepal und eine schöne Ergänzung für alle, die die Klassiker schon kennen. Er passt zu Wanderern, die 5–6 Stunden am Tag auf Bergpfaden schaffen, zu Familien mit älteren Kindern, zu Fotografen, die Sonnenauf- und -untergang vom selben Gipfel erleben wollen, und zu allen, die ihren Urlaub lieber mit Wandern als mit Warten am Flughafen verbringen. Wenn du wenig Zeit hast, aber den Everest mit eigenen Augen sehen willst, ist er kaum zu schlagen.", "type": "text"}]}]}, "heading": "Für wen der Pikey Peak passt", "tocLabel": "Für wen"}$de$::jsonb where section_id = 'e11c5321-ebd9-4bde-be12-6d1a96d424b2' and locale = 'de';
update public.article_section_translations set content = $de${"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Der Pikey Peak liegt außerhalb der Nationalparks, deshalb brauchst du keine Parkgenehmigung. An lokalen Kontrollposten wird manchmal nach einer TIMS-Karte gefragt, und nach den Regeln Nepals ist ein lizenzierter Guide Pflicht. Bei jedem unserer Treks ist er dabei.", "type": "text"}]}]}}$de$::jsonb where section_id = '2c22f008-0861-4743-aa4d-d3bf82c0fbc0' and locale = 'de';
update public.article_section_translations set content = $de${"body": {"type": "doc", "content": [{"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Die Fahrt ist lang.", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Rechne mit 8–10 Stunden auf Bergstraßen bis zum Ausgangspunkt. Nimm Snacks und Geduld mit.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Die Nächte sind kalt.", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Im Pikey Base Camp fällt die Temperatur außerhalb des Sommers weit unter null. Ein guter Schlafsack hat einen echten Unterschied gemacht.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Nimm Bargeld mit.", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Unterwegs gibt es keine Geldautomaten; Zimmer, Essen und heiße Duschen bezahlst du in nepalesischen Rupien.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Geh im Herbst oder Winter, wegen der Aussicht.", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Von Oktober bis Dezember hatte ich klare, frische Morgen.", "type": "text"}]}]}]}]}, "heading": "Praktisches, das ich gern vorher gewusst hätte", "tocLabel": "Praktische Tipps"}$de$::jsonb where section_id = 'bcfd237d-4ad1-4386-a086-d444585fd995' and locale = 'de';
update public.article_section_translations set content = $de${"items": [{"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Ja. An einem klaren Morgen stehen Everest, Lhotse, Makalu und Kanchenjunga alle am Horizont. Am besten siehst du sie bei Sonnenaufgang vom Gipfel aus.", "type": "text"}]}]}, "question": "Sieht man vom Pikey Peak wirklich den Everest?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Leicht bis mittelschwer. Die Etappen dauern 5–6 Stunden, der höchste Punkt liegt auf 4.065 m. Am anstrengendsten ist der frühe Aufstieg zum Gipfel für den Sonnenaufgang.", "type": "text"}]}]}, "question": "Wie schwer ist der Pikey Peak Trek?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Mit dem Jeep von Kathmandu nach Dhap, etwa 8–10 Stunden. Der Trek endet bei Phaplu. Von dort fährst du zurück oder fliegst nach Kathmandu, wenn Flüge gehen.", "type": "text"}]}]}, "question": "Wie kommt man zum Pikey Peak?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Eine Nationalpark-Genehmigung brauchst du nicht, da der Trek außerhalb der Parks liegt. An lokalen Kontrollposten wird manchmal nach einer TIMS-Karte gefragt, und wir haben dabei, was nötig ist.", "type": "text"}]}]}, "question": "Brauche ich eine Genehmigung für den Pikey Peak?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Oktober bis Dezember für die klarste Sicht, März bis Mai für blühende Rhododendren. Die Monsunmonate Juni bis August sind nass und wolkig.", "type": "text"}]}]}, "question": "Wann ist die beste Reisezeit für den Pikey Peak?"}]}$de$::jsonb where section_id = '21f02789-de91-4b99-8981-b5a350d6d080' and locale = 'de';
update public.article_section_translations set content = $de${"heading": "Lust auf eine Woche im Sherpa-Land?", "message": "Hallo! Ich interessiere mich für den Pikey Peak Trek und würde gern mehr über Termine und Preise erfahren.", "buttonText": "Pikey Peak per WhatsApp anfragen"}$de$::jsonb where section_id = '3448a4e2-30c4-420d-8168-8aac0e06686c' and locale = 'de';
update public.article_translations set facts = $de$[{"icon": "altitude", "label": "Versichert bis", "value": "Höchster Punkt deines Treks"}, {"icon": "description", "label": "Muss enthalten", "value": "Hubschrauberevakuierung"}, {"icon": "schedule", "label": "Sinnvoll", "value": "Schutz bei Flugverspätung"}]$de$::jsonb, intro = $de$Wer in Nepal trekkt, braucht eine Reiseversicherung, die Trekking in großer Höhe und die Rettung per Hubschrauber abdeckt. Hier erfährst du, worauf du im Kleingedruckten achten solltest und was du unterwegs dabeihaben musst.$de$, title = $de$Reiseversicherung fürs Trekking in Nepal: Das solltest du vor dem Abschluss prüfen$de$, card_text = $de$Höhengrenze, Hubschrauberrettung und Flugverspätungen: die Fragen, die du vor dem Abschluss klären solltest.$de$, cover_alt = $de$Der Khumbu-Gletscher und verschneite Gipfel, von Kala Patthar in der Everest-Region aus gesehen$de$, seo_title = $de$Reiseversicherung Nepal Trekking: Darauf musst du achten$de$, seo_keyword = $de$Reiseversicherung Nepal Trekking$de$, updated_line = $de$Aktualisiert für die Saison 2026/2027$de$, highlight_tag = $de$Rettungsschutz ist Pflicht$de$, seo_description = $de$Reiseversicherung Nepal Trekking: Prüfe vor dem Abschluss Höhengrenze, Hubschrauberrettung, Arztkosten und Flugverspätungen – plus was du unterwegs dabeihast.$de$ where article_id = 'a253ee04-585b-49fa-8e76-9f1050db808d' and locale = 'de';
update public.article_section_translations set content = $de${"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Schließ eine Reiseversicherung ab, die ", "type": "text"}, {"text": "Trekking bis zum höchsten Punkt deines Treks abdeckt", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (zum Beispiel 5.545 m beim Everest Base Camp Trek) und ", "type": "text"}, {"text": "Hubschrauberevakuierung und medizinische Notfallversorgung", "type": "text", "marks": [{"type": "bold"}]}, {"text": " einschließt. Prüfe auch, ob geführtes Trekking ohne Seil, deine Vorerkrankungen und Verspätungen bei Bergflügen versichert sind. Wir fragen alle Trekker vor dem Trek nach ihren Versicherungsdaten.", "type": "text"}]}]}}$de$::jsonb where section_id = '41479bd4-6452-47e0-a651-f49144d505ce' and locale = 'de';
update public.article_section_translations set content = $de${"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Meine erste Trekkingversicherung habe ich in aller Eile abgeschlossen, am Abend vor dem Flug nach Kathmandu. Erst unterwegs habe ich gelesen, dass sie Wandern nur bis 3.000 m abdeckte – und ich wollte auf 5.400 m. Es ist nichts passiert, aber ich wusste den ganzen Trek über, dass ich eine Rettung selbst hätte bezahlen müssen.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Diesen Ratgeber hätte ich damals gern gelesen. Er enthält allgemeine Hinweise, keine Empfehlung für einen bestimmten Versicherer. Ang Dorje Sherpa, der seit 20 Jahren als Guide im Khumbu unterwegs ist, hat die Abschnitte über Rettungen am Berg geprüft.", "type": "text"}]}]}}$de$::jsonb where section_id = 'edd826d0-005d-4824-b81a-f16615a3729e' and locale = 'de';
update public.article_section_translations set content = $de${"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Die meisten Treks in Nepal liegen Tagesmärsche von der nächsten Straße entfernt. Bist du ernsthaft krank oder verletzt, geht es oft nur per Hubschrauber hinaus, und das nächste passende Krankenhaus ist in Kathmandu. Deshalb setzen wir für unsere Treks eine Versicherung mit Evakuierungsschutz voraus, und deshalb fragt dich dein Guide vor dem Start nach deiner Policennummer.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Dein Guide und unser Büro in Kathmandu können eine Rettung schnell organisieren, aber meist muss der Versicherer sie erst genehmigen. Mit der richtigen Police und ihrer Notrufnummer in der Tasche sparst du Stunden, wenn es darauf ankommt.", "type": "text"}]}]}, "heading": "Warum die Versicherung in den Bergen zählt", "tocLabel": "Warum sie zählt"}$de$::jsonb where section_id = '0c104e20-a710-4d31-83dc-0163db65c67e' and locale = 'de';
update public.article_section_translations set content = $de${"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Viele Policen decken Wandern oder Trekking nur bis zu einer bestimmten Höhe ab. Führt dein Trek höher hinauf, bist du an den hohen Tagen womöglich gar nicht versichert – und genau an diesen Tagen passiert am ehesten etwas.", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Everest Base Camp:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " bis 5.545 m (Kala Patthar).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Annapurna Circuit:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " bis 5.416 m (Thorong La).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Manaslu Circuit:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " bis 5.106 m (Larkya La).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Langtang-Tal:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " bis 4.773 m (Kyanjin Ri) oder 4.984 m, wenn du auf den Tserko Ri steigst.", "type": "text"}]}]}]}, {"type": "paragraph", "content": [{"text": "Entscheidend ist der höchste Punkt des Treks, nicht der Ort, an dem du übernachtest. Auf unseren Trekseiten findest du ihn in den Eckdaten.", "type": "text"}]}]}, "heading": "Die Höhengrenze: Lies das zuerst", "tocLabel": "Höhengrenze"}$de$::jsonb where section_id = 'cf1645e1-b369-4a25-8c19-c449be0893fa' and locale = 'de';
update public.article_section_translations set content = $de${"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Liegt die Höhengrenze deiner Police unter dem höchsten Punkt deines Treks, frag den Versicherer vor der Reise nach einer Erweiterung oder nach einer speziellen Trekkingversicherung. Verlass dich nicht darauf, dass eine normale Urlaubsversicherung den Himalaya abdeckt.", "type": "text"}]}]}}$de$::jsonb where section_id = '1a764c76-049e-4924-bcf3-22b8151feb1e' and locale = 'de';
update public.article_section_translations set content = $de${"items": ["Trekking bis zum höchsten Punkt deines Treks", "Suche, Rettung und Evakuierung per Hubschrauber", "Medizinische Notfallbehandlung und Krankenhausaufenthalt", "Rücktransport in dein Heimatland, falls nötig", "Geführtes Trekking auf Wegen, ohne Seil und Kletterausrüstung", "Deine Vorerkrankungen, angegeben und vom Versicherer akzeptiert", "Reiserücktritt und vorzeitiger Abbruch des Treks", "Verspätungen und verpasste Anschlüsse durch gestrichene Bergflüge"], "heading": "Was deine Police abdecken sollte"}$de$::jsonb where section_id = '2caf2f50-9dd2-44c9-b6f3-bae14de7c397' and locale = 'de';
update public.article_section_translations set content = $de${"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Treks, die über kleine Bergflugplätze laufen, etwa Lukla in der Everest-Region, verzögern sich oft wetterbedingt, manchmal um einen Tag oder länger. In der Hauptsaison starten die meisten Lukla-Flüge in Ramechhap (Manthali), ein paar Autostunden von Kathmandu entfernt.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Wir planen Puffertage in unsere Everest-Reiseverläufe ein, aber eine lange Verspätung kann trotzdem heißen, dass du deinen internationalen Flug verpasst. Prüfe deshalb, ob Reiseverspätungen und verpasste Abflüge versichert sind und ob deine Police einen Teil eines Hubschrauberflugs hinaus übernimmt, wenn keine Flugzeuge landen können.", "type": "text"}]}]}, "heading": "Flugverspätungen in den Bergen", "tocLabel": "Flugverspätungen"}$de$::jsonb where section_id = 'fd0bc329-3481-4451-a498-87a94746a253' and locale = 'de';
update public.article_section_translations set content = $de${"text": "Speichere die 24-Stunden-Notrufnummer deines Versicherers im Handy und leg sie zusätzlich auf Papier in deinen Tagesrucksack. Wenn ich unser Büro wegen einer Rettung anrufe, fragt der Versicherer als Erstes nach der Policennummer."}$de$::jsonb where section_id = 'e178ab9a-669a-45da-a081-bbdc341a418f' and locale = 'de';
update public.article_section_translations set content = $de${"body": {"type": "doc", "content": [{"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Deine Policennummer und die 24-Stunden-Notrufnummer des Versicherers, auf Papier und im Handy.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Eine Kopie deines Reisepasses und deiner Genehmigungen.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Eine kurze Notiz zu Vorerkrankungen, Allergien und Medikamenten in deinem Tagesrucksack.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Ein geladenes Handy oder eine Powerbank. In vielen Dörfern gibt es Mobilfunkempfang, und dein Guide hat die Kontakte unseres Büros dabei.", "type": "text"}]}]}]}, {"type": "paragraph", "content": [{"text": "Außerdem bewahren wir eine Kopie deiner Versicherungsdaten in unserem Büro in Kathmandu auf, damit wir mit deinem Versicherer sprechen können, wenn du es nicht kannst.", "type": "text"}]}]}, "heading": "Was du unterwegs dabeihaben solltest", "tocLabel": "Unterwegs"}$de$::jsonb where section_id = 'af8ca3ee-1f06-49ee-ba8c-c930723bc979' and locale = 'de';
update public.article_section_translations set content = $de${"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Die meisten Treks enden ohne jedes Problem. Wird doch jemand krank oder verletzt sich, läuft es meist so ab:", "type": "text"}]}, {"type": "orderedList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Dein Guide leistet Erste Hilfe, misst mit dem Pulsoximeter deine Sauerstoffsättigung und beginnt bei Höhenproblemen sofort mit dem Abstieg.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Kannst du nicht sicher zu Fuß absteigen, ruft dein Guide unser Büro in Kathmandu an und gibt deinen Standort und deinen Zustand durch.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Wir melden uns mit deiner Policennummer bei deinem Versicherer und organisieren den Hubschrauber, sobald die Rettung genehmigt ist.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Du wirst zur Behandlung nach Kathmandu geflogen, und wir bleiben mit dir, deiner Familie und dem Versicherer in Kontakt.", "type": "text"}]}]}]}, {"type": "paragraph", "content": [{"text": "Absteigen ist die wichtigste Behandlung bei Höhenkrankheit, und dafür wartet man nie auf einen Hubschrauber. Wann immer es möglich ist, beginnt dein Guide den Abstieg zu Fuß.", "type": "text"}]}]}, "heading": "Wenn auf dem Trek etwas passiert", "tocLabel": "Im Notfall"}$de$::jsonb where section_id = '5359f59e-c84f-40e3-b045-fe1e26d61955' and locale = 'de';
update public.article_section_translations set content = $de${"body": {"type": "doc", "content": [{"type": "orderedList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Bis zu welcher Höhe bin ich versichert, und zählt dabei der höchste Punkt, den ich an einem Tag erreiche?", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Ist eine Hubschrauberevakuierung versichert, und muss die Versicherung sie vor dem Start genehmigen?", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Ist ein geführter Trek auf Wegen standardmäßig versichert oder nur als Zusatzaktivität?", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Sind meine Vorerkrankungen versichert, wenn ich sie angebe?", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Was ist abgedeckt, wenn ein Bergflug mehrere Tage lang ausfällt?", "type": "text"}]}]}]}, {"type": "paragraph", "content": [{"text": "Lass dir die Antworten schriftlich geben, per E-Mail oder in den Versicherungsunterlagen, bevor du bezahlst.", "type": "text"}]}]}, "heading": "Vor dem Abschluss: Diese Fragen stellst du dem Versicherer", "tocLabel": "Fragen an den Versicherer"}$de$::jsonb where section_id = '28ea94d0-44c7-48e0-8b48-2d988b09c25b' and locale = 'de';
update public.article_section_translations set content = $de${"items": [{"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Auf unseren Treks braucht jeder eine Reiseversicherung, die Trekking in der Höhe des Treks und eine Hubschrauberevakuierung im Notfall abdeckt. Wir fragen dich vor dem Start des Treks nach deinen Versicherungsdaten.", "type": "text"}]}]}, "question": "Ist eine Reiseversicherung für einen Trek in Nepal Pflicht?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Oft nur bis zu einer bestimmten Höhe, manchmal gar nicht. Lies die Abschnitte zu Aktivitäten und Höhe in deiner Police und schließ eine Erweiterung oder eine spezielle Trekkingversicherung ab, wenn dein Trek höher hinaufführt.", "type": "text"}]}]}, "question": "Deckt eine normale Reiseversicherung Trekking ab?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Dein Guide meldet sich bei unserem Büro in Kathmandu, und wir koordinieren die Rettung mit deinem Versicherer. Deshalb brauchen wir deine Policennummer und die Notrufnummer des Versicherers.", "type": "text"}]}]}, "question": "Wer ruft im Notfall den Hubschrauber?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Dein Guide hilft dir, sicher abzusteigen. Ob die Mehrkosten übernommen werden, hängt von deiner Police ab. Prüfe also, was sie für einen Reiseabbruch vorsieht.", "type": "text"}]}]}, "question": "Was ist, wenn ich den Trek nicht zu Ende gehen möchte?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Ja. Die Höhe ist geringer, aber Unfälle und Krankheiten gibt es auf jedem Trek. Achte darauf, dass deine Police Trekking und Evakuierung für deine Route abdeckt.", "type": "text"}]}]}, "question": "Brauche ich auch für einen kurzen Trek wie Poon Hill eine Versicherung?"}]}$de$::jsonb where section_id = '8f9a1c46-75d2-48a2-bc6b-691c736e2449' and locale = 'de';
update public.article_section_translations set content = $de${"heading": "Fragen zur Versicherung für deinen Trek?", "message": "Hallo! Ich schließe gerade eine Reiseversicherung für meinen Trek ab. Könnt ihr mir sagen, wie hoch der höchste Punkt meiner Route liegt und welchen Versicherungsschutz ihr braucht?", "buttonText": "Auf WhatsApp fragen"}$de$::jsonb where section_id = '0d874ddc-aa18-4a17-b640-de216abd18ff' and locale = 'de';

-- People
update public.author_translations set bio = $de$Rajan kümmert sich bei jedem unserer Treks um Genehmigungen, Flüge und Transport. Er schreibt unsere Ratgeber zu Nepals Trekking-Regeln und hält sie aktuell, wenn sich die Regeln ändern.$de$, job_title = $de$Leiter Genehmigungen und Logistik$de$ where author_id = 'e57d393a-2755-4cd1-9951-deb8b3493919' and locale = 'de';
update public.author_translations set bio = $de$Maya betreut unsere Reiseratgeber als Redakteurin und geht jeden Artikel mit einem Guide aus der Region durch, bevor er online geht. Sie ist in Pokhara aufgewachsen, am Fuß der Annapurnas.$de$, job_title = $de$Redakteurin Reiseratgeber$de$ where author_id = '50690fec-bc03-41bc-9111-15014c3c51bb' and locale = 'de';
update public.author_translations set job_title = $de$Leitender Trek-Guide, Everest-Region$de$ where author_id = 'e68497a1-c472-4ea8-8b0f-6448bae462da' and locale = 'de';
update public.author_translations set bio = $de$Tom ist zum Everest Base Camp und rund um den Manaslu gewandert und schreibt ehrliche Tipps zu Ausrüstung und Budget für alle, die ihre erste große Trekkingreise planen.$de$, job_title = $de$Trekker und Reiseautor$de$ where author_id = '7b982214-6e85-4da9-bcb1-5ec1acbe8843' and locale = 'de';
update public.author_translations set bio = $de$Ich bin Sandip Kshetri, lizenzierter Guide, und habe über 200 Reisende durch Nepal geführt. Ich gebe dir ehrliche, praktische Ratschläge, damit du selbst entscheidest, wie deine Reise aussieht. Wir bleiben flexibel, behandeln unser Team fair und stellen deine Sicherheit immer an erste Stelle.$de$, job_title = $de$Gründer und Leiter der Treks$de$ where author_id = '1eadb781-2205-49a2-9d6d-7ec17205d5a9' and locale = 'de';
update public.trekking_guide_translations set bio = $de$Ramesh ist in Salleri in den unteren Solu-Hügeln aufgewachsen und arbeitet seit 10 Jahren als Guide. Als begeisterter Fotograf weiß er, wo bei Sonnenaufgang auf dem Pikey Peak das Licht hinfällt, und hilft Trekkern, die Bilder zu machen, für die sie gekommen sind.$de$, role = $de$Trek-Guide und Fotograf$de$, quote = $de$Das schönste Foto vom Everest entsteht oft auf einem stillen Hügel, auf dem du die Aussicht ganz für dich hast.$de$ where guide_id = '05e60394-900d-4ec4-b01c-0a20c811521f' and locale = 'de';
update public.trekking_guide_translations set bio = $de$Ang Dorje stammt aus Khumjung unterhalb der Ama Dablam und ist seit 20 Jahren Guide im Khumbu. Er ist in Wildnis-Erster-Hilfe ausgebildet, leitet unsere Treks zum Everest Base Camp und zu den Gokyo-Seen und plant jeden Reiseverlauf rund um eine sichere Akklimatisierung.$de$, role = $de$Leitender Trek-Guide, Everest-Region$de$, quote = $de$Wir steigen langsam auf und schauen jeden Abend nach allen. Der Berg läuft uns nicht weg.$de$ where guide_id = 'e43057dc-d551-4178-9210-2eb06a88240c' and locale = 'de';

-- About, Contact and the legal pages (from Annapurna Trekking's German, in du-form and about Everest)
update public.site_pages set eyebrow = $de$Unser Team ist online · Kathmandu$de$, heading = $de$Sprich mit einem einheimischen Trekking-Experten$de$, intro = $de$Frag uns alles, von „Welcher Trek passt zu mir?“ bis zu Genehmigungen, Lukla-Flügen und Preisen. Ein echter Mensch aus unserem Team in Kathmandu antwortet dir, meist innerhalb weniger Stunden. Kostenlos und ohne Buchungsverpflichtung.$de$, seo_title = $de$Kontakt: Everest Trek, deine Trekking Agentur in Nepal$de$, seo_description = $de$Frag das Team von Everest Trek in Kathmandu per WhatsApp oder E-Mail alles zu deinem Trek. Antwort meist in wenigen Stunden, kostenlos und unverbindlich.$de$, seo_keyword = $de$Trekking Agentur Nepal Kontakt$de$, content = $de${"faqs": [{"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Per WhatsApp meist innerhalb weniger Stunden während der Bürozeiten in Nepal, per E-Mail innerhalb von 24 Stunden.", "type": "text"}]}]}, "question": "Wie schnell bekomme ich eine Antwort?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Nein. Fragen, Vorschläge und Reiseverläufe sind kostenlos und ohne Buchungsverpflichtung.", "type": "text"}]}]}, "question": "Kostet eine Anfrage etwas?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Diese Website speichert deine Nachricht nicht. Sie öffnet WhatsApp oder dein E-Mail-Programm, und wir verwenden deine Angaben nur, um dir zu antworten.", "type": "text"}]}]}, "question": "Werden meine Daten gespeichert?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Ja. Schreib uns auf WhatsApp, und wir vereinbaren einen Sprach- oder Videoanruf zu einer Zeit, die dir passt.", "type": "text"}]}]}, "question": "Können wir telefonieren?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Natürlich. Komm während der Öffnungszeiten im Büro vorbei, oder schreib uns, und wir treffen uns mit dir.", "type": "text"}]}]}, "question": "Ich bin schon in Kathmandu. Kann ich vorbeikommen?"}], "timeNote": "Außerhalb dieser Zeiten? Hinterlass uns eine WhatsApp-Nachricht. Wir antworten gleich am nächsten Morgen.", "nextSteps": [{"text": "Nenn uns deine Reisedaten, die Gruppengröße und was du gern sehen möchtest. Auch reine Fragen sind willkommen.", "when": "Heute", "title": "Du schickst uns eine Nachricht"}, {"text": "Ein Experte vor Ort schlägt dir den passenden Trek vor, mit Reiseverlauf Tag für Tag und einem klaren Preis für deine Gruppe.", "when": "Innerhalb weniger Stunden", "title": "Wir antworten mit Plan und Preis"}, {"text": "Wir buchen Genehmigungen, Flüge, Guides und Lodges. Du kannst den Plan kostenlos ändern, bis er passt.", "when": "Wenn du bereit bist", "title": "Du bestätigst mit 10 % Anzahlung"}], "timeZones": ["Europe/Berlin", "Europe/London", "America/New_York"], "faqHeading": "Bevor du uns schreibst", "replyTimes": {"email": "Antwort innerhalb von 24 Stunden", "whatsApp": "Antwortet meist innerhalb weniger Stunden"}, "officeDirections": ""}$de$::jsonb, updated_at = now() where site_id = 'everest' and slug = 'contact';
update public.site_pages set eyebrow = $de$$de$, heading = $de$Cookie-Einstellungen$de$, intro = $de$Wähle, was diese Website laden darf. Notwendige Funktionen sind immer aktiv; alles andere bleibt ausgeschaltet, bis du es erlaubst.$de$, seo_title = $de$$de$, seo_description = $de$$de$, seo_keyword = $de$$de$, content = $de${"body": {"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Was wir verwenden", "type": "text"}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Name", "type": "text"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Zweck", "type": "text"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Speicherdauer", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "consent", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Speichert deine Auswahl auf dieser Seite", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "12 Monate", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Google Analytics", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Zählt Seitenaufrufe, geladen über den Google Tag Manager (nur mit deiner Einwilligung)", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Von Google festgelegt", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Google Maps", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Interaktive Routen- und Bürokarten (nur mit deiner Einwilligung)", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Von Google festgelegt", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "YouTube", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Trekking-Videos im erweiterten Datenschutzmodus (nur mit deiner Einwilligung)", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Von Google festgelegt", "type": "text"}]}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Meinung geändert?", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Du kannst jederzeit über den Link „Cookie-Einstellungen“ unten auf jeder Seite zu dieser Seite zurückkehren. Der Widerruf deiner Einwilligung berührt nicht die Rechtmäßigkeit dessen, was vorher geladen wurde.", "type": "text"}]}]}, "autoDate": true, "lastUpdated": "2026-10-29", "lawyerChecked": false}$de$::jsonb, updated_at = now() where site_id = 'everest' and slug = 'cookies';
update public.site_pages set eyebrow = $de$$de$, heading = $de$Datenschutzerklärung$de$, intro = $de$Wie wir mit deinen personenbezogenen Daten umgehen, wenn du diese Website besuchst oder uns kontaktierst. Kurz gesagt: Wir erheben so wenig wie möglich.$de$, seo_title = $de$$de$, seo_description = $de$$de$, seo_keyword = $de$$de$, content = $de${"body": {"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Verantwortlicher", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "{company}, {address}. E-Mail: {email}. [EU-Vertreter nach Art. 27 DSGVO].", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Was diese Website nicht tut", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Auf dieser Website gibt es keine Benutzerkonten und keine Online-Zahlungen.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Unsere Kontakt- und Buchungsformulare senden oder speichern nichts auf unseren Servern. Sie öffnen nur WhatsApp oder dein E-Mail-Programm.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Schriftarten liegen auf unserem eigenen Server, es gehen also keine Daten an Google Fonts.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Server-Logfiles", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Wenn du eine Seite aufrufst, erfasst unser Hosting-Anbieter automatisch technische Daten wie IP-Adresse, Datum und Uhrzeit, aufgerufene Seite und Browser. Das ist nötig, um die Website sicher auszuliefern (Art. 6 Abs. 1 lit. f DSGVO), und wird nach 30 Tagen gelöscht. Hosting: Vercel Inc., auf Servern von Amazon Web Services (AWS) in Deutschland.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Kontakt per WhatsApp oder E-Mail", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Wenn du uns schreibst, verwenden wir deinen Namen, deine Kontaktdaten und deine Nachricht nur, um dir zu antworten und deinen Trek zu planen (Art. 6 Abs. 1 lit. b DSGVO). WhatsApp ist ein Dienst der WhatsApp Ireland Ltd. (Meta); dabei können Daten in die USA übermittelt werden. Wenn du das nicht möchtest, kontaktiere uns stattdessen per E-Mail.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Zählung von Button-Klicks", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Wir zählen Klicks auf unsere WhatsApp- und E-Mail-Buttons, ohne Cookies und ohne deine IP-Adresse zu speichern, um zu sehen, welche Seiten weiterhelfen. Diese Zahlen lassen keinen Rückschluss auf deine Person zu.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Cookies, Analyse und externe Medien", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Analysedienste nutzen wir und externe Medien (Google Maps, YouTube) laden wir nur, wenn du in unseren Cookie-Einstellungen eingewilligt hast (Art. 6 Abs. 1 lit. a DSGVO). Du kannst deine Auswahl jederzeit unter Cookie-Einstellungen ändern.", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Analyse: Google Analytics, geladen über den Google Tag Manager, um zu verstehen, welche Seiten gelesen werden", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Google Maps: zeigt Routenkarten und unser Büro, wird erst nach deinem Klick geladen", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "YouTube (erweiterter Datenschutzmodus): Trekking-Videos, werden erst nach deinem Klick geladen", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Wie lange wir Daten speichern", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Nachrichten zu einem Trek speichern wir so lange, wie es für die Planung und für gesetzliche Aufbewahrungspflichten in Nepal nötig ist. Wir speichern diese Daten 12 Monate lang und löschen sie dann.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Deine Rechte", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Du kannst jederzeit Auskunft über deine Daten, deren Berichtigung, Löschung, Einschränkung der Verarbeitung oder eine Kopie (Datenübertragbarkeit) verlangen, der Verarbeitung widersprechen oder deine Einwilligung widerrufen. Außerdem hast du das Recht, dich bei einer Datenschutz-Aufsichtsbehörde zu beschweren, zum Beispiel bei der Behörde an deinem Wohnort.", "type": "text"}]}]}, "autoDate": true, "lastUpdated": "2026-10-29", "lawyerChecked": false}$de$::jsonb, updated_at = now() where site_id = 'everest' and slug = 'privacy';
update public.site_pages set eyebrow = $de$$de$, heading = $de$AGB und Buchungsbedingungen$de$, intro = $de$Diese Bedingungen gelten, wenn du einen Trek bei Everest Trek buchst. Bitte lies sie, bevor du eine Anzahlung leistest.$de$, seo_title = $de$$de$, seo_description = $de$$de$, seo_keyword = $de$$de$, content = $de${"body": {"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Wer wir sind", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Diese Bedingungen gelten für Treks, die von {company}, {address}, organisiert werden, registriert beim Department of Tourism unter der Nr. {licence} („wir“, „uns“).", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "So funktioniert die Buchung", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Du planst deinen Trek mit uns per WhatsApp oder E-Mail. Deine Buchung ist bestätigt, sobald wir deine Anzahlung erhalten und dir eine schriftliche Bestätigung mit Reiseverlauf und Reisepreis geschickt haben.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Preise und Zahlung", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Die Preise gelten pro Person in Euro und richten sich nach der Gruppengröße. Was im Preis enthalten ist und was nicht, steht auf jeder Trek-Seite und in deiner Bestätigung.", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Anzahlung: 10 % des Reisepreises zur Bestätigung deiner Buchung", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Restzahlung: fällig bei Ankunft in Kathmandu", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Zahlungsarten: bar oder per Banküberweisung", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Änderungen und Absage durch uns", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Bergwetter, Erdrutsche, gesperrte Wege, ausgefallene Flüge oder Sicherheitsbedenken können Änderungen erzwingen. Dein Guide kann die Route ändern oder umkehren, wenn das Weitergehen nicht sicher ist. Sagen wir vor der Abreise ab, bekommst du alles, was du uns gezahlt hast, vollständig zurück.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Rücktritt durch dich", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Bitte teile uns deinen Rücktritt schriftlich mit (per E-Mail oder WhatsApp). Was du zurückbekommst, hängt davon ab, wie lange vor Beginn deines Treks wir von dir hören:", "type": "text"}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Zeitpunkt des Rücktritts", "type": "text"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Erstattung", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Mehr als 72 Stunden vor deinem Trek", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Volle Erstattung, abzüglich Bankgebühren und etwaiger Kosten für Genehmigungen", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Zwischen 72 und 48 Stunden vor deinem Trek", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Erstattung abzüglich der Kosten, die wir für deinen Trek bereits bezahlt haben", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Weniger als 48 Stunden vorher oder Nichterscheinen", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Keine Erstattung: Der volle Reisepreis wird berechnet", "type": "text"}]}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Vorzeitige Rückkehr", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Kehrst du gleich aus welchem Grund vorzeitig von deinem Trek zurück, können wir nichts erstatten. Deine Guides und Träger werden weiterhin für alle ursprünglich gebuchten Tage bezahlt.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Änderungen durch dich", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Du kannst Reisedaten, Route oder Gruppengröße vor der Abreise kostenlos ändern, sofern verfügbar. Mehrkosten, etwa für zusätzliche Tage oder Genehmigungen, berechnen wir zum Selbstkostenpreis.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Verspätungen und Ausfälle von Inlandsflügen", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Bergflüge in Nepal, vor allem nach und von Lukla, verspäten sich wetterbedingt oft oder fallen aus. In diesem Fall trägst du die Kosten für dadurch nötige zusätzliche Hotelnächte.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Versicherung, Gesundheit und Fitness", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Eine persönliche Reiseversicherung ist Pflicht. Sie muss Notfälle abdecken, einschließlich Trekking in den Höhen deines Treks und Hubschrauberrettung. Unsere eigenen Guides und Träger versichern wir selbst. Du bestätigst, dass du für den gebuchten Trek fit genug bist, und informierst uns über relevante gesundheitliche Einschränkungen.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Dokumente und Genehmigungen", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Du brauchst einen Reisepass, der noch mindestens sechs Monate gültig ist, und ein Visum für Nepal. Wir besorgen deine Trekking-Genehmigungen; du stellst uns rechtzeitig Passkopien und Passfotos zur Verfügung.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Unsere Verantwortung", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Wir planen und führen deinen Trek mit angemessener Sorgfalt und Sachkenntnis durch, mit lizenzierten Guides und bewährten Partnern vor Ort wie Lodges, Fahrern und Fluggesellschaften. Wir sind für die Erbringung der in deiner Bestätigung aufgeführten Leistungen verantwortlich.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Trekking im Himalaya birgt natürliche Risiken, darunter Höhenkrankheit, plötzliche Wetterumschwünge, Erdrutsche und raue Wege. Wir verringern diese Risiken mit Akklimatisierungstagen, täglichen Gesundheitschecks und einem Rettungsplan, können sie aber nicht ausschließen. Mit deiner Buchung akzeptierst du diese Risiken.", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Wir haften nicht für Verletzungen, Krankheiten, Verluste, Verspätungen oder Mehrkosten durch Ereignisse außerhalb unserer Kontrolle, etwa Wetter, Naturkatastrophen, Streiks, politische Unruhen, behördliche Entscheidungen, Straßensperrungen oder Verspätungen und Ausfälle von Flügen durch Fluggesellschaften.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Wir haften nicht für Probleme, die entstehen, weil du die Sicherheitsanweisungen deines Guides nicht befolgt hast, oder durch gesundheitliche Einschränkungen, die du uns nicht mitgeteilt hast.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Bitte bewahre Geld, Reisepass und Wertsachen sicher auf. Für Verlust oder Beschädigung deiner persönlichen Gegenstände haften wir nicht.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Notfallkosten wie Hubschrauberrettung, Krankenhausbehandlung oder zusätzliche Übernachtungen trägst du selbst bzw. deine Reiseversicherung.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Soweit wir haften, ist unsere Haftung auf den Betrag begrenzt, den du uns für deinen Trek gezahlt hast, außer wenn das Gesetz diese Begrenzung nicht zulässt.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Beschwerden", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Bitte sag deinem Guide oder unserem Büro sofort Bescheid, wenn etwas nicht stimmt, damit wir es vor Ort beheben können. Bist du danach noch unzufrieden, schreib uns innerhalb von 30 Tagen nach Ende deines Treks eine E-Mail.", "type": "text"}]}]}, "autoDate": true, "lastUpdated": "2026-10-29", "lawyerChecked": false}$de$::jsonb, updated_at = now() where site_id = 'everest' and slug = 'terms';
update public.site_pages set eyebrow = $de$Über uns$de$, heading = $de$Privattreks in der Everest-Region, so wie du sie dir erträumst.$de$, intro = $de$Everest Trek ist ein lizenzierter Trekkingveranstalter in Kathmandu. Wir planen Privattreks in der Everest-Region, zum Everest Base Camp, zu den Gokyo-Seen und auf den Pikey Peak. Vier Überzeugungen prägen jede Reise, und alles beginnt damit, dass wir dir zuhören.$de$, seo_title = $de$Über uns: Everest Trek, Trekking Agentur in Nepal$de$, seo_description = $de$Lerne Everest Trek kennen, deine Trekking Agentur in Nepal: unser Team in Kathmandu, unsere Geschichte, Lizenzen und wie wir für Träger und Dörfer sorgen.$de$, seo_keyword = $de$Trekking Agentur Nepal$de$, content = $de${"goals": [{"text": "Guides, Träger und Trekking-Mitarbeiter bekommen oft nicht den Respekt und die Bezahlung, die sie verdienen. Das wollen wir ändern, und es beginnt damit, wie wir unser eigenes Team behandeln.", "title": "Respekt und faire Bezahlung für das Team am Weg"}, {"text": "Viele wunderschöne Gegenden Nepals sehen bis heute nur sehr wenige Besucher. Wir möchten sie zeigen und Reisenden einen Grund geben, über die berühmten Wege hinauszugehen.", "title": "Orte, die die Aufmerksamkeit der Welt verdienen"}, {"text": "Wir möchten, dass der Tourismus Familien in ganz Nepal ein echtes Einkommen bringt. Wir sind überzeugt, dass das in vielen Regionen noch gut möglich ist, und jeder Trek, den wir planen, ist ein Schritt dorthin.", "title": "Tourismus, der die Menschen vor Ort stärkt"}], "quote": "Es ist Zeit, dass Nepal seine eigene Stimme bekommt.", "honest": {"body": "Ehrlich heißt: Wir nennen dir die echten Kosten, den echten Andrang, die echte Schwierigkeit und die echten Risiken. Vorausschauend heißt: Wir sprechen Probleme als Erste an, ob ein besserer Monat, ein ausgefallener Flug nach Lukla oder ein Trek, der für deine erste Reise zu hoch ist. Wir sagen es dir, auch wenn du den Trek deshalb absagst. Die Entscheidung triffst du.", "quote": "Wir sagen dir, was wir wissen. Du entscheidest.", "advice": [{"who": "An jemanden, der zum ersten Mal trekkt", "quote": "Für deinen ersten Trek passt der Pikey Peak vielleicht besser als das Everest Base Camp."}, {"who": "An einen Gast, der ruhige Wege sucht", "quote": "Wenn du volle Lodges nicht magst, meide im Oktober den Hauptweg zum Basislager. Die Gokyo-Seen oder der Pikey Peak sind ruhiger."}, {"who": "An einen Gast, der für Juli bucht", "quote": "Deine Reisedaten fallen in den Monsun, und Flüge nach Lukla fallen dann oft aus. Warte lieber auf den Herbst."}, {"who": "An einen Gast mit wenig Zeit", "quote": "Die längere Variante brauchst du nicht. Sieben Tage reichen für das, was du sehen möchtest."}], "points": [{"text": "Wir sagen es, wenn ein kürzerer, günstigerer oder leichterer Trek besser zu dir passt oder wenn du eine zusätzliche Leistung nicht brauchst.", "title": "Vor der Buchung"}, {"text": "Vollständige Preise, was nicht enthalten ist, ehrliche Hinweise und für wen der Trek nicht geeignet ist.", "title": "Auf jeder Trek-Seite"}, {"text": "Wir melden uns zuerst, wenn sich Wetter, Flüge nach Lukla oder Genehmigungen ändern, und sagen dir, was das für deinen Plan bedeutet.", "title": "Vor dem Abflug"}, {"text": "Dein Guide erklärt dir den Grund für jede Umkehr und jede Routenänderung. Wenn wir einen Fehler machen, geben wir ihn zu und beheben ihn.", "title": "Unterwegs"}], "eyebrow": "02 · Ehrlich und vorausschauend", "heading": "Wir beraten dich immer ehrlich, auch wenn uns das eine Buchung kostet.", "cardLink": "Ratschläge, die wir immer geben", "cardText": "Wir sagen dir die Wahrheit, bevor du fragst, auch wenn du den Trek dann vielleicht absagst.", "cardTitle": "Wir sind ehrlich", "adviceHeading": "Ratschläge, die wir geben, auch wenn wir dadurch weniger buchen"}, "listen": {"body": "Bevor wir eine Route vorschlagen, hören wir zu. Wir möchten deine Gedanken, deine Interessen und deine Vorlieben kennen. Wir möchten auch wissen, wie du Entscheidungen triffst und warum dir diese Reise wichtig ist.\r\n\r\nWenn wir das verstanden haben, schlagen wir den Reiseverlauf vor, der am besten zu dir passt. Vielleicht ist es nicht der berühmteste Trek. Aber es ist der richtige für dich.", "quote": "Erst hören wir zu, dann planen wir rund um dich.", "steps": [{"text": "Wir stellen offene Fragen und lassen dich erzählen. Es gibt keine Formulare und kein Verkaufsgespräch nach Schema.", "title": "1. Wir hören zu"}, {"text": "Wir schauen über den Namen des Treks hinaus auf das, was du wirklich suchst.", "title": "2. Wir verstehen"}, {"text": "Erst dann schlagen wir eine Route vor: den richtigen Trek, die richtige Zahl an Tagen und das richtige Tempo für dich, mit einer Begründung für jede Entscheidung.", "title": "3. Wir schlagen vor"}], "example": "Wer zum ersten Mal trekkt, Angst vor steilen Anstiegen hat und ruhige Wege sucht, hört von uns vielleicht eher „Pikey Peak, mit dem Everest am Horizont“ als „Everest Base Camp“.", "eyebrow": "01 · Wir hören zuerst zu", "heading": "Erst verstehen wir dich. Dann schlagen wir den Trek vor, der zu dir passt.", "cardLink": "Wie wir zuhören", "cardText": "Wir verstehen, was du dir von Nepal wünschst, bevor wir einen Reiseverlauf vorschlagen.", "cardTitle": "Wir hören zuerst zu", "questions": ["Wie bist du auf Nepal gekommen?", "Was machst du auf Reisen am liebsten?", "Was soll diese Reise für dich bedeuten?", "Gibt es etwas, das du vermeiden möchtest?"], "understand": [{"label": "Deine Gedanken", "value": "Was du dir vorstellst"}, {"label": "Deine Interessen", "value": "Gipfel, Dörfer, Essen"}, {"label": "Deine Vorlieben", "value": "Tempo, Komfort, Andrang"}, {"label": "Dein Anliegen", "value": "Warum diese Reise, warum jetzt"}], "understandNote": "Wir lernen auch, wie du Entscheidungen triffst, damit wir dir unsere Vorschläge so erklären, wie es dir am meisten hilft."}, "safety": {"facts": [{"text": "Fester Bestandteil jedes Treks in großer Höhe.", "title": "Akklimatisierungstage"}, {"text": "Sauerstoff und Puls, jeden Abend.", "title": "Tägliche Gesundheitschecks"}, {"text": "Koordiniert von unserem Büro in Kathmandu.", "title": "Rettungsplan"}], "eyebrow": "Die eine Regel über allen vier", "heading": "Dein Trek, dein Weg. Nur bei deiner Sicherheit machen wir keine Kompromisse."}, "flexible": {"body": "Wir verkaufen kein fertiges Paket, in das du hineinpassen musst. Dein Privattrek entsteht aus dem, was du uns erzählt hast, und du kannst ihn so lange ändern, bis er sich richtig anfühlt.\r\n\r\nAuch nach der Buchung bleibt der Plan flexibel. Möchtest du mitten im Trek etwas ändern, sind wir immer offen und tun unser Bestes, um es möglich zu machen. Brauchst du einen Ruhetag, ein langsameres Tempo oder eine Nacht mehr in einem Dorf? Dein Guide kann das unterwegs ändern, und unser Büro in Kathmandu bucht Lodges, Jeeps und Flüge noch am selben Tag um.", "quote": "Wenn es machbar ist, machen wir es.", "stages": [{"text": "Du bekommst zwei oder drei Varianten desselben Treks zum Vergleich. Änderungen sind kostenlos, bis der Plan passt.", "title": "Vor der Buchung"}, {"text": "Deine eigenen Reisedaten und deine eigene Gruppe, ohne fremde Mitreisende. Dein Plan nennt deinen Guide und erklärt, warum jeder Tag so geplant ist, wie er ist.", "title": "Buchung"}, {"text": "Einen Ruhetag einlegen, das Tempo drosseln, einen Abstecher machen oder länger in einem Dorf bleiben, wenn es sicher ist und die Genehmigungen es erlauben.", "title": "Unterwegs"}, {"text": "Wir helfen bei zusätzlichen Tagen in Nepal, umgebuchten Flügen oder der Planung deiner nächsten Reise.", "title": "Nach dem Trek"}], "eyebrow": "03 · Privat und flexibel", "heading": "Wir passen den Plan an dich an, nicht umgekehrt.", "cardLink": "Wie sich Pläne ändern lassen", "cardText": "Möchtest du den Plan mitten im Trek ändern, sind wir immer offen und tun unser Bestes, um es möglich zu machen.", "cardTitle": "Wir sind flexibel", "quoteNote": "Auch wenn es für unser Team mehr Arbeit, eine neue Buchung oder ein langes Telefonat bedeutet.", "limitsLead": "Wo die Flexibilität endet, ganz ehrlich:", "limitsText": "Sicherheit geht immer vor. Genehmigungen und gebuchte Flüge nach Lukla legen manche Reisedaten fest. Zusätzliche Tage unterwegs kosten zusätzliche Guide-, Träger- und Lodgetage, und diese Kosten nennen wir dir, bevor wir etwas ändern. Änderungen vor der Buchung sind immer kostenlos.", "photoCaption": "Auf 4.980 m beim Langtang Valley Trek, 2025", "stagesHeading": "Wie dein Trek flexibel bleibt"}, "openMind": {"body": "Offenheit schenkt dir neue Blickwinkel und neue Erlebnisse. Das gilt überall, aber ganz besonders in den Bergen Nepals, wo jedes Tal seine eigene Lebensweise hat.", "more": "Zwei Menschen können denselben Weg gehen und von zwei ganz verschiedenen Reisen heimkehren. Wer verschlossen unterwegs ist, dem kommen Berge, Flüsse und Wälder nach ein paar Tagen alle gleich vor.\r\n\r\nWer offen ist, bemerkt die Unterschiede. Fels und Bäume ändern sich, je höher du steigst. Essen und Gebetsfahnen ändern sich von Tal zu Tal. Dörfer der Sherpa, Tamang, Gurung und tibetischen Buddhisten leben jeweils auf ihre eigene Weise. Gerade diese Neugier ist oft das, woran sich unsere Gäste am meisten erinnern.", "quote": "Bring einfach Offenheit mit.", "places": [{"text": "Der Marktort der Sherpa, in Terrassen an den Hang über dem Tal gebaut.", "title": "Namche Bazar, Khumbu"}, {"text": "Ein Kloster auf einem Bergrücken, mit der Ama Dablam im Blick.", "title": "Tengboche, Khumbu"}, {"text": "Steinhäuser am Ufer der Gokyo-Seen, abseits des Hauptwegs zum Basislager.", "title": "Gokyo, Khumbu"}], "eyebrow": "04 · Unsere wichtigste Überzeugung", "heading": "Offenheit macht deine Reise besser.", "invites": [{"text": "eine kurze Einführung in die Dörfer, Kulturen und Bräuche auf deiner Route, mit ein paar nepalesischen Wörtern zum Ausprobieren.", "title": "Vor dem Trek:"}, {"text": "Dein Guide zeigt dir, was sich von Tal zu Tal ändert, etwa Häuser, Felder, Essen, Feste und Glauben, nicht nur die Gipfel.", "title": "Unterwegs:"}, {"text": "eine Einladung zum Tee, ein Besuch im Kloster, ein Essen im Dorf oder ein Abstecher zu einem Aussichtspunkt.", "title": "Kleine „Ja“-Momente:"}], "cardLink": "Warum das wichtig ist", "cardText": "Neugier schenkt dir in den Bergen neue Blickwinkel und neue Erlebnisse.", "cardTitle": "Wir glauben an Offenheit", "quoteNote": "Um den Rest kümmern wir uns.", "inviteNote": "Wir laden ein, wir belehren nie. Respekt vor den Menschen vor Ort steht immer an erster Stelle.", "inviteHeading": "Wie wir dich einladen"}, "promises": [{"icon": "tune", "text": "Jeder Trek ist privat, damit der Plan zu dir passt. Du möchtest einen zusätzlichen Ruhetag, ein langsameres Tempo oder eine andere Route? Sag es uns, und wir ändern es ohne Aufpreis.", "title": "Ganz auf dich zugeschnitten"}, {"icon": "chat", "text": "Wir beraten dich so, wie wir einen Freund beraten würden, auch wenn du dann weniger bei uns buchst. Unsere Preise sind transparent, ohne versteckte Gebühren.", "title": "Ehrliche Gespräche"}, {"icon": "shield_person", "text": "Dein Guide ist in diesen Bergen aufgewachsen und kennt jede Biegung des Weges, den du gehst.", "title": "Guides, die in diesen Bergen zu Hause sind"}, {"icon": "health_and_safety", "text": "Wir planen in jeden Reiseverlauf Akklimatisierungstage ein, messen täglich deine Sauerstoffsättigung und haben auf jedem Trek einen Rettungsplan bereit. Pläne können sich ändern, die Sicherheit nie.", "title": "Deine Sicherheit geht vor"}, {"icon": "verified", "text": "Wir sind bei der Regierung von Nepal und bei TAAN registriert. Du buchst direkt bei unserem Team in Nepal, ohne Zwischenhändler. Unsere Träger tragen begrenzte Lasten und bekommen warme Ausrüstung, eine Versicherung und faire Löhne.", "title": "Einheimisch, lizenziert und fair zu unserem Team"}, {"icon": "temple_buddhist", "text": "Unterwegs nimmt dich dein Guide mit in Sherpa-Häuser, stille Klöster und einheimische Küchen. Viele Gäste erzählen uns, dass diese Momente ihren Blick auf Nepal verändert haben.", "title": "Mehr als ein Trek"}], "statLabel": "Guides aus ihren eigenen Tälern", "statValue": "Alle", "storyText": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Ich bin Sandip Kshetri, lizenzierter Guide aus Mirlung, einem Dorf am Hang im Distrikt Tanahun nahe dem Annapurna-Gebiet. Ich habe mehr als 200 Reisende durch Nepal geführt.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Meine Reise begann 2022 auf dem Mardi Himal Trek.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "An einem klaren Nachmittag blieb ich stehen und sah einer kleinen Wolke zu, die über die Annapurna South zog. Wie ich so dastand, war es, als würde der Berg mir etwas zuflüstern. In diesem Moment wurde mir klar, dass Berge, Flüsse und Wälder ihre eigene Stimme haben und wir nur zuhören müssen. Von diesem Tag an wurde meine Liebe zur Natur und zu den Bergen immer stärker. Diese Leidenschaft führte mich in den Tourismus, und 2025 habe ich Everest Trek mitgegründet.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Ich habe diese Firma gegründet, um in meinem eigenen Land zu bleiben und ihm etwas zurückzugeben. Wir zahlen unseren Guides und Trägern 50 % mehr als branchenüblich, und kein Träger trägt mehr als 20 kg. Außerdem zeigen wir Nepal durch einheimische Stimmen, auch kleine Dörfer, von denen die meisten Reisenden nie hören.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Wir trekken langsam und mit offenen Augen, damit du die Dörfer, Flüsse und Wälder wahrnimmst, nicht nur den Gipfelblick. Vor allem steht für uns immer deine Sicherheit an erster Stelle.", "type": "text"}]}]}, "teamIntro": "Lizenzierte Guides aus den Bergen Nepals und ein kleines Büro in Kathmandu, das deine Nachrichten beantwortet.", "voiceText": "Uns ist noch etwas aufgefallen. Wir Nepalesen haben in der Welt nur selten eine eigene Stimme. Viel zu oft stellen ausländische Firmen und Menschen Nepal auf ihre eigene Weise dar.\r\n\r\nWir sind allen, die unser Land bekannt gemacht haben, von Herzen dankbar und werden ihren Beitrag nie vergessen. Aber es ist Zeit, dass wir Nepalesen selbst zur Welt sprechen.\r\n\r\nMit Everest Trek möchten wir Nepal auf unsere eigene Weise zeigen. Wenn wir wachsen, werden wir Dokumentationen, Geschichten und Videos über Nepal machen, damit andere nicht mehr auf der Weltbühne für uns sprechen müssen.", "safetyLead": "Alle vier beruhen auf einer Regel:", "safetyText": "Deine Sicherheit geht vor.", "storyTeaser": "Ich bin Sandip Kshetri, lizenzierter Guide aus Mirlung, einem Dorf am Hang im Distrikt Tanahun nahe dem Annapurna-Gebiet. Ich habe mehr als 200 Reisende durch Nepal geführt.\r\n\r\nMeine Reise begann 2022 auf dem Mardi Himal Trek. \r\nAn einem klaren Nachmittag blieb ich stehen und sah einer kleinen Wolke zu, die über die Annapurna South zog. Wie ich so dastand, war es, als würde der Berg mir etwas zuflüstern. In diesem Moment wurde mir klar, dass Berge, Flüsse und Wälder ihre eigene Stimme haben und wir nur zuhören müssen. Von diesem Tag an wurde meine Liebe zur Natur und zu den Bergen immer stärker. Diese Leidenschaft führte mich in den Tourismus, und 2025 habe ich Everest Trek mitgegründet.\r\nIch habe diese Firma gegründet, um in meinem eigenen Land zu bleiben und ihm etwas zurückzugeben. Wir zahlen unseren Guides und Trägern 50 % mehr als branchenüblich, und kein Träger trägt mehr als 20 kg. Außerdem zeigen wir Nepal durch einheimische Stimmen, auch kleine Dörfer, von denen die meisten Reisenden nie hören.\r\nWir trekken langsam und mit offenen Augen, damit du die Dörfer, Flüsse und Wälder wahrnimmst, nicht nur den Gipfelblick. Vor allem steht für uns immer deine Sicherheit an erster Stelle.", "teamHeading": "Die Menschen, die deinen Trek planen und führen", "storyHeading": "Lerne Sandip Kshetri kennen, den Gründer von Everest Trek", "voiceEyebrow": "Unsere Stimme", "voiceHeading": "Nepal, gezeigt so, wie Einheimische es zeigen würden", "founderOrigin": "Aus Tanahun, nahe dem Annapurna-Gebiet", "licencesIntro": "Jede Zahl unten kannst du beim Department of Tourism in Nepal und bei TAAN überprüfen.", "promisesIntro": "", "trekkersGuided": "50+", "licencesHeading": "Registriert, lizenziert und versichert", "promisesHeading": "", "trekkingRegions": ""}$de$::jsonb, updated_at = now() where site_id = 'everest' and slug = 'about';
update public.site_pages set eyebrow = $de$$de$, heading = $de$Impressum$de$, intro = $de$Rechtliche Angaben zu dieser Website (Angaben gemäß § 5 DDG und § 18 MStV für Besucher aus Deutschland).$de$, seo_title = $de$$de$, seo_description = $de$$de$, seo_keyword = $de$$de$, content = $de${"body": {"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Anbieter", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "{company}", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "{address}", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Vertreten durch", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Sandip Kshetri, CEO", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Kontakt", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Telefon: {phone}", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "WhatsApp: {phone}", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "E-Mail: {email}", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Registrierung und Lizenzen", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "{registers}", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Verbraucherstreitbeilegung", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Wir sind nicht bereit oder verpflichtet, an Streitbeilegungsverfahren vor einer Verbraucherschlichtungsstelle teilzunehmen.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Fotos", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Alle Fotos auf dieser Website sind unsere eigenen, sofern nicht anders angegeben.", "type": "text"}]}]}, "autoDate": true, "lastUpdated": "2026-10-29", "lawyerChecked": false}$de$::jsonb, updated_at = now() where site_id = 'everest' and slug = 'impressum';

-- Home: the Everest Base Camp Trek, the top of the page from the design, and the blog page's top --------------------

update public.site_pages p
set eyebrow = 'Privater Trek mit Sherpa-Guide',
    heading = 'Everest Base Camp Trek',
    intro = '14 Tage zum Fuß des höchsten Bergs der Welt: Bergflug nach Lukla, Namche Bazar, das Kloster Tengboche und Sonnenaufgang am Kala Patthar (5.545 m). Privat, mit lizenziertem Guide, Start an jedem Tag.',
    seo_title = 'Everest Base Camp Trek: 14 Tage privat mit Sherpa-Guide',
    seo_description = 'Privater Everest Base Camp Trek in 14 Tagen mit lizenziertem Sherpa-Guide: Lukla, Namche, Tengboche, zwei Ruhetage und Kala Patthar. Start an jedem Tag.',
    seo_keyword = 'Everest Base Camp Trek',
    photo_id = (select t.cover_photo_id from public.treks t where t.site_id = 'everest' and t.slug = 'everest-base-camp'),
    content = '{"photoAlt": "Everest, Nuptse und Lhotse über dem Khumbu-Tal", "buttonLabel": "Trek per WhatsApp planen", "secondLabel": "Zum Reiseverlauf"}'::jsonb,
    updated_at = now()
where p.site_id = 'everest' and p.slug = 'home';

update public.site_pages p
set eyebrow = 'Lies, bevor du losgehst',
    heading = 'Everest Trek Blog',
    intro = 'Reisezeit, Höhe, Lukla-Flüge und Versicherung: ehrliche Tipps von unserem Team, das jede Saison im Khumbu unterwegs ist.',
    seo_title = 'Everest Trek Blog: Reisezeit, Höhe, Lukla-Flug und Tipps',
    seo_description = 'Plane deinen Everest Trek mit unseren Ratgebern: beste Reisezeit, Höhenkrankheit, Lukla-Flüge, Reiseversicherung und Pikey Peak, vom Team aus Kathmandu.',
    seo_keyword = 'Everest Trek Tipps',
    updated_at = now()
where p.site_id = 'everest' and p.slug = 'travel-guides';

