-- The website has never been live, so it has no old addresses to keep.
delete from public.slug_redirects where site_id = 'everest';

do $$
begin
  if exists (select 1 from public.trek_translations x join public.treks t on t.id = x.trek_id where t.site_id = 'everest' and x.name in ('Gokyo Lakes Trek'))
     or exists (select 1 from public.site_pages where site_id = 'everest' and slug = 'about' and content::text like '%Sie %') then
    raise exception 'The Everest website still has English or formal text';
  end if;
end;
